INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1684', 'استپ‌آپ تک‌پا با تعادل و جلو بازو دمبل', 'Dumbbell step up single leg balance with bicep curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'چهارسر ران، سرینی (باسن)، همسترینگ (پشت ران)', '۱. جلوی پله یا سکو بایستید و در هر دست یک دمبل با کف دست رو به بدن بگیرید.
۲. پای راست را روی پله بگذارید و مطمئن شوید تمام کف پا روی سطح است.
۳. میان‌تنه را درگیر کنید و با فشار پاشنه راست روی پله بروید و زانوی چپ را به سمت سینه بالا بیاورید.
۴. در اوج حرکت، با خم کردن آرنج‌ها و آوردن دمبل‌ها به سمت شانه‌ها یک جلو بازو انجام دهید.
۵. دمبل‌ها را پایین بیاورید و همزمان پای چپ را به زمین برگردانید.
۶. حرکت را برای طرف مقابل با بالا رفتن پای چپ و جلو بازو تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1684.gif', 'biceps', 'quadriceps,gluteal,hamstring', '1. Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.
2. Place your right foot on the step, ensuring your entire foot is in contact with the surface.
3. Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.
4. At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.
5. Lower the dumbbells back down and simultaneously lower your left foot back to the ground.
6. Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.
7. Continue alternating sides for the desired number of repetitions.', '1684') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0431', 'استپ‌آپ دمبل', 'Dumbbell step-up', 'legs', 'پا', 'dumbbell', 'دمبل', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. جلوی نیمکت یا پله بایستید و در هر دست یک دمبل با کف دست رو به بدن بگیرید.
۲. پای راست را روی نیمکت یا پله بگذارید و مطمئن شوید تمام کف پا روی سطح است.
۳. با فشار پاشنه راست بدن را روی نیمکت یا پله بالا ببرید و پای راست را صاف کنید.
۴. پای چپ را هم روی نیمکت یا پله بیاورید و کاملاً صاف بایستید.
۵. ابتدا با پای چپ و سپس با پای راست پایین بیایید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0431.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.
2. Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.
3. Push through your right heel and lift your body up onto the bench or step, straightening your right leg.
4. Bring your left foot up onto the bench or step, standing fully upright.
5. Step back down with your left foot, followed by your right foot, returning to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '0431') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2796', 'استپ‌آپ و لانج دمبل', 'Dumbbell step-up lunge', 'legs', 'پا', 'dumbbell', 'دمبل', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. جلوی پله یا سکو بایستید و در هر دست یک دمبل با کف دست رو به پهلوها بگیرید.
۲. پای راست را روی پله بگذارید و مطمئن شوید تمام کف پا روی سطح است.
۳. با فشار پاشنه راست بدن را روی پله ببرید و پای چپ را هم بالا بیاورید.
۴. وقتی هر دو پا روی پله بودند، پای چپ را به وضعیت شروع پایین بیاورید و پای راست روی پله بماند.
۵. حرکت را تکرار کنید و هر بار پای بالارونده را عوض کنید.
۶. به تعداد تکرار دلخواه ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2796.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.
2. Place your right foot on the step, ensuring your entire foot is on the surface.
3. Push through your right heel and lift your body up onto the step, bringing your left foot up as well.
4. Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.
5. Repeat the movement, alternating which foot you step up with each time.
6. Continue for the desired number of repetitions.', '2796') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2812', 'استپ‌آپ و اسکوات اسپلیت دمبل', 'Dumbbell step-up split squat', 'legs', 'پا', 'dumbbell', 'دمبل', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. جلوی نیمکت یا پله بایستید و در هر دست یک دمبل با کف دست رو به بدن بگیرید.
۲. پای راست را روی نیمکت یا پله بگذارید و مطمئن شوید تمام کف پا روی سطح است.
۳. با پای راست روی نیمکت یا پله بروید و با فشار پاشنه بدن را بالا ببرید.
۴. همزمان با بالا رفتن، زانوی چپ را به سمت سینه بالا بیاورید.
۵. در اوج حرکت مکث کنید، سپس پای چپ را آرام به زمین برگردانید و پای راست روی نیمکت یا پله بماند.
۶. حرکت را با پای چپ روی نیمکت یا پله تکرار کنید.
۷. به تعداد تکرار دلخواه پای راست و چپ را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2812.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.
2. Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.
3. Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.
4. As you step up, simultaneously lift your left knee towards your chest.
5. Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.
6. Repeat the movement with your left foot on the bench or step.
7. Continue alternating between your right and left foot for the desired number of repetitions.', '2812') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0432', 'ددلیفت پا صاف دمبل', 'Dumbbell stiff leg deadlift', 'legs', 'پا', 'dumbbell', 'دمبل', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل را از رو بگیرید.
۲. با کمر صاف و میان‌تنه درگیر، از لگن خم شوید و دمبل‌ها را به سمت زمین پایین ببرید و اجازه دهید زانوها کمی خم شوند.
۳. دمبل‌ها را تا جایی پایین ببرید که کشش را در همسترینگ حس کنید، سپس باسن را منقبض کرده و با فشار پاشنه‌ها به وضعیت شروع برگردید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0432.gif', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.
3. Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.
4. Repeat for the desired number of repetitions.', '0432') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0433', 'پول‌اور دست صاف دمبل', 'Dumbbell straight arm pullover', 'chest', 'سینه', 'dumbbell', 'دمبل', 'سینه', 'زیربغل، پشت بازو', '۱. روی نیمکت صاف دراز بکشید؛ سر در یک انتهای نیمکت و پاها محکم روی زمین.
۲. یک دمبل را با دو دست بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. با دست‌های صاف، دمبل را آرام در مسیری کمانی پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس دمبل را به وضعیت شروع بالا بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0433.gif', 'chest', 'upper-back,triceps', '1. Lie flat on a bench with your head at one end and your feet planted firmly on the ground.
2. Hold a dumbbell with both hands and extend your arms straight above your chest.
3. Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.
4. Pause for a moment, then raise the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions.', '0433') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0434', 'ددلیفت پا مستقیم دمبل', 'Dumbbell straight leg deadlift', 'legs', 'پا', 'dumbbell', 'دمبل', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل را از رو بگیرید.
۲. با کمر صاف و میان‌تنه درگیر، از لگن خم شوید و دمبل‌ها را به سمت زمین پایین ببرید و اجازه دهید تنه به جلو متمایل شود.
۳. دمبل‌ها را تا جایی پایین ببرید که کشش را در همسترینگ حس کنید و زانوها را کمی خم نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با درگیر کردن باسن و همسترینگ تنه را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0434.gif', 'gluteal', 'hamstring,lower-back', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.
3. Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.
4. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.
5. Repeat for the desired number of repetitions.', '0434') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2808', 'پول‌ترو سومو دمبل', 'Dumbbell sumo pull through', 'legs', 'پا', 'dumbbell', 'دمبل', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، میان‌تنه', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را به بیرون بچرخانید.
۲. یک دمبل را با دو دست جلوی بدن با دست‌های صاف نگه دارید.
۳. زانوها را خم کنید و لگن را به حالت اسکوات پایین ببرید و کمر را صاف نگه دارید.
۴. دمبل را با دست‌های صاف بین پاها پایین ببرید.
۵. با فشار پاشنه‌ها لگن را به جلو برانید و دمبل را بالا و جلوی بدن بکشید.
۶. در اوج حرکت باسن را منقبض کنید، سپس دمبل را دوباره بین پاها پایین ببرید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2808.gif', 'gluteal', 'hamstring,quadriceps,abs', '1. Stand with your feet wider than shoulder-width apart, toes pointed outwards.
2. Hold a dumbbell with both hands in front of your body, arms extended.
3. Bend your knees and lower your hips down into a squat position, keeping your back straight.
4. Lower the dumbbell down between your legs, keeping your arms straight.
5. Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.
6. Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.
7. Repeat for the desired number of repetitions.', '2808') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2803', 'اسکوات با تکیه‌گاه دمبل', 'Dumbbell supported squat', 'legs', 'پا', 'dumbbell', 'دمبل', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل کنار بدن بگیرید.
۲. سینه را بالا و میان‌تنه را درگیر نگه دارید و با خم کردن زانوها و بردن لگن به عقب آرام پایین بروید.
۳. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2803.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.
2. Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.
3. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
4. Pause for a moment at the bottom, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '2803') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0436', 'پرس تیت دمبل', 'Dumbbell tate press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت صاف بنشینید و در هر دست یک دمبل با کف دست‌های رو به هم بگیرید.
۲. دمبل‌ها را تا ارتفاع شانه بالا بیاورید، سپس مچ‌ها را بچرخانید تا کف دست‌ها رو به بیرون باشد.
۳. دمبل‌ها را بالا پرس کنید تا دست‌ها کاملاً صاف شوند، سپس تا ارتفاع شانه پایین بیاورید.
۴. مچ‌ها را به حالت اول برگردانید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0436.gif', 'triceps', 'deltoids', '1. Sit on a flat bench with a dumbbell in each hand, palms facing each other.
2. Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.
3. Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.
4. Rotate your wrists back to the starting position and repeat for the desired number of repetitions.', '0436') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1742', 'کیک‌بک پشت بازو روی یک پا دمبل', 'Dumbbell tricep kickback with stork stance', 'arms', 'بازو', 'dumbbell', 'دمبل', 'پشت بازو', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک دمبل در دست راست بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. آرنج راست را تا کنار بدن بالا بیاورید و آن را ۹۰ درجه خم نگه دارید.
۴. دست راست را صاف به عقب باز کنید و پشت بازو را منقبض کنید.
۵. لحظه‌ای مکث کنید، سپس دمبل را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1742.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Bring your right elbow up to your side, keeping it bent at a 90-degree angle.
4. Extend your right arm straight back, squeezing your triceps.
5. Pause for a moment, then slowly lower the dumbbell back to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '1742') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1743', 'پرس سینه چرخشی دمبل', 'Dumbbell twisting bench press', 'arms', 'بازو', 'dumbbell', 'دمبل', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. در هر دست یک دمبل را از رو با کف دست رو به بیرون بگیرید.
۳. دست‌ها را صاف بالای سینه ببرید و آرنج‌ها را کمی خم نگه دارید.
۴. دمبل‌ها را به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. هنگام پایین آوردن دمبل‌ها، مچ‌ها را بچرخانید تا در پایین حرکت کف دست‌ها رو به شما باشد.
۶. لحظه‌ای در پایین مکث کنید، سپس حرکت را معکوس کنید و دمبل‌ها را به وضعیت شروع پرس کنید.
۷. هنگام پرس دمبل‌ها، مچ‌ها را به حالت اول با کف دست رو به بیرون برگردانید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1743.gif', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Hold a dumbbell in each hand with an overhand grip, palms facing away from you.
3. Extend your arms straight up over your chest, keeping a slight bend in your elbows.
4. Lower the dumbbells down towards your chest, keeping your elbows close to your body.
5. As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.
6. Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.
7. As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.
8. Repeat for the desired number of repetitions.', '1743') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0437', 'کول ایستاده دمبل', 'Dumbbell upright row', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل را از رو بگیرید.
۲. دمبل‌ها را با دست‌های کاملاً صاف جلوی ران‌ها آویزان کنید.
۳. با کمر صاف و میان‌تنه درگیر، با بازدم دمبل‌ها را با هدایت آرنج‌ها مستقیم به سمت چانه بالا بکشید.
۴. لحظه‌ای در بالا مکث کنید، سپس با دم دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0437.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Let the dumbbells hang in front of your thighs, with your arms fully extended.
3. Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.
4. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '0437') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1765', 'کول ایستاده دمبل (نمای پشت)', 'Dumbbell upright row (back pov)', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل را از رو بگیرید.
۲. دمبل‌ها را با دست‌های کاملاً صاف و کف دست رو به بدن جلوی ران‌ها آویزان کنید.
۳. با کمر صاف و میان‌تنه درگیر، با بازدم دمبل‌ها را با هدایت آرنج‌ها مستقیم به سمت چانه بالا بکشید.
۴. تا جایی بالا بکشید که دمبل‌ها در ارتفاع شانه و آرنج‌ها رو به طرفین باشند.
۵. لحظه‌ای در بالا مکث کنید، سپس با دم دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1765.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.
2. Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.
3. Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.
4. Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.
5. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.
6. Repeat for the desired number of repetitions.', '1765') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0864', 'چرخش خارجی شانه ایستاده دمبل', 'Dumbbell upright shoulder external rotation', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'روتاتور کاف، کول (ذوزنقه)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل با کف دست رو به بدن بگیرید.
۲. دست‌ها را به طرفین بالا ببرید تا موازی زمین شوند و آرنج‌ها را کمی خم نگه دارید.
۳. دست‌ها را به بیرون بچرخانید و دمبل‌ها را به سمت سر بالا ببرید و آرنج‌ها را در همان وضعیت نگه دارید.
۴. لحظه‌ای در بالا مکث کنید، سپس دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0864.gif', 'deltoids', 'trapezius', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.
2. Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.
3. Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.
4. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '0864') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_5201', 'جلو بازو گارسونی دمبل', 'Dumbbell waiter biceps curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'ساعد، شانه‌ها', '۱. صاف بایستید و در هر دست یک دمبل با کف دست رو به جلو بگیرید.
۲. بازوها را نزدیک بدن و آرنج‌ها را جمع نگه دارید.
۳. دمبل‌ها را آرام به سمت شانه‌ها بالا بیاورید و مچ‌ها را صاف نگه دارید.
۴. لحظه‌ای در بالا مکث کنید، سپس دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/5201.gif', 'biceps', 'forearm,deltoids', '1. Stand up straight with a dumbbell in each hand, palms facing forward.
2. Keep your upper arms close to your body and your elbows tucked in.
3. Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.
4. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
5. Repeat for the desired number of repetitions.', '5201') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0438', 'پرس W دمبل', 'Dumbbell w-press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'پشت بازو، سینه', '۱. روی نیمکت بنشینید و در هر دست یک دمبل با کف دست رو به جلو بگیرید.
۲. دمبل‌ها را با آرنج‌های خم و کف دست رو به جلو تا ارتفاع شانه بالا بیاورید.
۳. دمبل‌ها را بالا پرس کنید تا دست‌ها کاملاً بالای سر صاف شوند.
۴. دمبل‌ها را تا ارتفاع شانه پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0438.gif', 'deltoids', 'triceps,chest', '1. Sit on a bench with a dumbbell in each hand, palms facing forward.
2. Raise the dumbbells to shoulder height, elbows bent and palms facing forward.
3. Press the dumbbells upward until your arms are fully extended overhead.
4. Lower the dumbbells back to shoulder height.
5. Repeat for the desired number of repetitions.', '0438') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0439', 'جلو بازو زاتمن دمبل', 'Dumbbell zottman curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'ساعد', '۱. صاف بایستید و در هر دست یک دمبل با کف دست رو به بدن بگیرید.
۲. آرنج‌ها را نزدیک تنه نگه دارید و کف دست‌ها را بچرخانید تا رو به جلو شوند.
۳. دمبل‌ها را تا شانه‌ها بالا بیاورید و بازوها را ثابت نگه دارید.
۴. در اوج حرکت مچ‌ها را بچرخانید تا کف دست‌ها رو به بیرون باشد.
۵. دمبل‌ها را آرام به وضعیت شروع پایین بیاورید و کف دست‌ها را دوباره رو به بدن بچرخانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0439.gif', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing your body.
2. Keep your elbows close to your torso and rotate your palms to face forward.
3. Curl the dumbbells up to your shoulders while keeping your upper arms stationary.
4. At the top of the movement, rotate your wrists so that your palms are facing away from your body.
5. Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.
6. Repeat for the desired number of repetitions.', '0439') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2294', 'جلو بازو زاتمن لاری دمبل', 'Dumbbell zottman preacher curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'ساعد', '۱. روی نیمکت لاری بنشینید و در هر دست یک دمبل با کف دست رو به بالا و آرنج‌ها روی پد بگیرید.
۲. دمبل‌ها را به سمت شانه‌ها بالا بیاورید و بازوها را ثابت و کف دست‌ها را رو به بالا نگه دارید.
۳. در بالای حرکت مچ‌ها را بچرخانید تا کف دست‌ها رو به پایین باشد.
۴. دمبل‌ها را آرام به وضعیت شروع پایین بیاورید و همزمان مچ‌ها را به حالت اول برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2294.gif', 'biceps', 'forearm', '1. Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.
2. Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.
3. At the top of the curl, rotate your wrists so that your palms are facing down.
4. Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.
5. Repeat for the desired number of repetitions.', '2294') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2189', 'پشت بازو نشسته با دو دمبل', 'Dumbbells seated triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. یک دمبل را با دو دست از رو بگیرید و بالای سر ببرید.
۳. آرنج‌ها را خم کنید و دمبل را پشت سر پایین ببرید و بازوها را نزدیک گوش‌ها نگه دارید.
۴. دست‌ها را صاف کنید و دمبل را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2189.gif', 'triceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell in both hands with an overhand grip, and raise it above your head.
3. Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.
4. Extend your arms and raise the dumbbell back to the starting position.
5. Repeat for the desired number of repetitions.', '2189') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1167', 'کشش پویای سینه', 'Dynamic chest stretch (male)', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'شانه‌ها، پشت بازو', '۱. صاف بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دست‌ها را صاف به طرفین و موازی زمین باز کنید.
۳. دست‌ها را آرام به جلو بیاورید و جلوی بدن ضربدری کنید.
۴. کشش را در عضلات سینه حس کنید.
۵. کشش را ۱۰ تا ۳۰ ثانیه نگه دارید.
۶. به وضعیت شروع برگردید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1167.gif', 'chest', 'deltoids,triceps', '1. Stand tall with your feet shoulder-width apart.
2. Extend your arms straight out to the sides, parallel to the ground.
3. Slowly bring your arms forward, crossing them in front of your body.
4. Feel the stretch in your chest muscles.
5. Hold the stretch for 10-30 seconds.
6. Return to the starting position and repeat for the desired number of repetitions.', '1167') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3287', 'دیپ آرنج', 'Elbow dips', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. لبه نیمکت یا صندلی بنشینید و لبه آن را کنار لگن با دست‌ها بگیرید.
۲. لگن را از نیمکت جلو ببرید و پاها را صاف کنید و پاشنه‌ها را روی زمین نگه دارید.
۳. آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید و کمر را نزدیک نیمکت نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار دست‌ها، دست‌ها را صاف کنید و بدن را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3287.gif', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.
2. Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.
3. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.
4. Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.
5. Repeat for the desired number of repetitions.', '3287') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1772', 'بالا آمدن روی آرنج - شنا معکوس', 'Elbow lift - reverse push-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'پشت بازو، شانه‌ها', '۱. روی زمین دمر دراز بکشید، پاها صاف و دست‌ها درست زیر شانه‌ها باشد.
۲. میان‌تنه را درگیر کنید و با فشار کف دست‌ها بالاتنه را از زمین بلند کنید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. لحظه‌ای در بالا مکث کنید و عضلات بالای کمر را منقبض کنید.
۴. بدن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1772.gif', 'upper-back', 'triceps,deltoids', '1. Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.
2. Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.
3. Pause at the top for a moment, squeezing your upper back muscles.
4. Slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', '1772') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0443', 'آرنج به زانو', 'Elbow-to-knee', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. به پشت صاف دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. شکم را درگیر کنید و بالاتنه را از زمین بلند کنید و آرنج راست را به سمت زانوی چپ ببرید.
۴. همزمان زانوی چپ را به سمت آرنج راست بیاورید تا حرکت چرخشی ایجاد شود.
۵. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام پایین بیاورید و پاها را به وضعیت شروع صاف کنید.
۶. حرکت را تکرار کنید و این بار آرنج چپ را به سمت زانوی راست و زانوی راست را به سمت آرنج چپ ببرید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0443.gif', 'abs', 'obliques', '1. Start by lying flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.
4. At the same time, bring your left knee towards your right elbow, creating a twisting motion.
5. Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.
6. Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.
7. Continue alternating sides for the desired number of repetitions.', '0443') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3292', 'آسانسور', 'Elevator', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'شانه‌ها، کول (ذوزنقه)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دست‌ها را روی لگن بگذارید یا جلوی سینه ضربدری کنید.
۳. با کمر صاف، آرام از کمر به جلو خم شوید و بالاتنه را به سمت زمین پایین ببرید.
۴. لحظه‌ای در پایین مکث کنید، سپس بالاتنه را آرام به وضعیت شروع بالا بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3292.gif', 'upper-back', 'deltoids,trapezius', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Place your hands on your hips or cross them in front of your chest.
3. Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.
4. Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.
5. Repeat for the desired number of repetitions.', '3292') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1332', 'بالا آوردن دست یک در میان روی توپ تعادلی', 'Exercise ball alternating arm ups', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'شانه‌ها، میان‌تنه', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. در هر دست یک دمبل با کف دست رو به داخل بگیرید و دست‌ها را صاف کنار بدن آویزان کنید.
۳. میان‌تنه را درگیر کنید و یک دست را آرام به سمت شانه بالا ببرید و آرنج را کمی خم نگه دارید.
۴. لحظه‌ای در بالا مکث کنید، سپس دست را آرام به وضعیت شروع پایین بیاورید.
۵. حرکت را با دست دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1332.gif', 'upper-back', 'deltoids,abs', '1. Sit on the stability ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.
3. Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.
4. Pause for a moment at the top, then slowly lower your arm back down to the starting position.
5. Repeat the movement with the other arm.
6. Continue alternating arms for the desired number of repetitions.', '1332') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1333', 'فیله کمر روی توپ تعادلی با دست‌های کشیده', 'Exercise ball back extension with arms extended', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. توپ تعادلی را روی زمین بگذارید و دمر روی آن دراز بکشید؛ لگن روی توپ و برای ثبات کف پاها به دیوار تکیه داشته باشد.
۲. دست‌ها را صاف جلوی بدن با کف دست رو به پایین دراز کنید.
۳. میان‌تنه را درگیر کنید و بالاتنه را آرام از روی توپ بلند کنید و کمر را صاف و گردن را در راستای ستون فقرات نگه دارید.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1333.gif', 'lower-back', 'gluteal,hamstring', '1. Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.
2. Extend your arms straight out in front of you, with your palms facing down.
3. Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '1333') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1334', 'فیله کمر روی توپ تعادلی با دست پشت سر', 'Exercise ball back extension with hands behind head', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. توپ تعادلی را روی زمین بگذارید و دمر روی آن دراز بکشید و لگن روی توپ باشد.
۲. برای حمایت کف پاها را به دیوار یا سطحی ثابت تکیه دهید.
۳. دست‌ها را پشت سر ضربدری کنید به طوری که دست‌ها پشت سر را لمس کنند.
۴. میان‌تنه را درگیر کنید و بالاتنه را آرام از روی توپ بلند کنید تا بدن از سر تا لگن یک خط صاف بسازد.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس بالاتنه را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1334.gif', 'lower-back', 'gluteal,hamstring', '1. Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.
2. Position your feet against a wall or other stable surface for support.
3. Cross your arms behind your head, with your hands touching the back of your head.
4. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.
5. Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.
6. Repeat for the desired number of repetitions.', '1334') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1335', 'فیله کمر روی توپ تعادلی با زانوی جدا از زمین', 'Exercise ball back extension with knees off ground', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. توپ تعادلی را روی زمین بگذارید و دمر روی آن دراز بکشید؛ لگن روی توپ و برای ثبات کف پاها به دیوار تکیه داشته باشد.
۲. دست‌ها را پشت سر یا ضربدری روی سینه بگذارید.
۳. میان‌تنه را درگیر کنید و بالاتنه را آرام از روی توپ بلند کنید و کمر را باز کنید تا بدن از سر تا پاشنه در یک خط صاف قرار بگیرد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1335.gif', 'lower-back', 'gluteal,hamstring', '1. Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.
2. Position your hands behind your head or crossed over your chest.
3. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '1335') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1336', 'فیله کمر روی توپ تعادلی با چرخش', 'Exercise ball back extension with rotation', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. دمر روی توپ تعادلی دراز بکشید، لگن روی توپ و کف پاها محکم روی زمین باشد.
۲. دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.
۳. میان‌تنه را درگیر کنید و بالاتنه را آرام از روی توپ بلند کنید و کمر را باز کنید تا بدن از سر تا پاشنه در یک خط صاف قرار بگیرد.
۴. لحظه‌ای در بالا مکث کنید، سپس تنه را آرام به یک طرف بچرخانید و لگن و پاها را ثابت نگه دارید.
۵. به مرکز برگردید و چرخش را به طرف دیگر تکرار کنید.
۶. بالاتنه را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1336.gif', 'lower-back', 'gluteal,hamstring', '1. Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.
2. Place your hands behind your head or cross them over your chest.
3. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.
4. Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.
5. Return to the center and repeat the rotation to the other side.
6. Lower your upper body back down to the starting position and repeat for the desired number of repetitions.', '1336') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1744', 'دیپ روی توپ تعادلی', 'Exercise ball dip', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. دست‌ها را کنار لگن روی توپ بگذارید، انگشتان رو به جلو.
۳. پشت بازو را درگیر کنید و با فشار دست‌ها بدن را از روی توپ بلند کنید و دست‌ها را صاف کنید.
۴. با خم کردن آرنج‌ها بدن را پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1744.gif', 'triceps', 'chest,deltoids', '1. Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Place your hands on the ball beside your hips, fingers pointing forward.
3. Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.
4. Lower your body back down by bending your elbows, keeping them close to your sides.
5. Repeat for the desired number of repetitions.', '1744') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1559', 'کشش خم‌کننده ران با توپ تعادلی', 'Exercise ball hip flexor stretch', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)', '۱. توپ تعادلی را روی زمین بگذارید و جلوی آن زانو بزنید.
۲. پای راست را روی توپ بگذارید و زانو را ۹۰ درجه خم کنید.
۳. پای چپ را صاف پشت سر دراز کنید.
۴. به جلو متمایل شوید و لگن را به سمت توپ فشار دهید تا کشش را در خم‌کننده ران راست حس کنید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس طرف را عوض کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1559.gif', 'gluteal', 'quadriceps,hamstring', '1. Place the stability ball on the ground and kneel in front of it.
2. Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.
3. Extend your left leg behind you, keeping it straight.
4. Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.
5. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '1559') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1338', 'بغل کردن توپ تعادلی', 'Exercise ball hug', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'شانه‌ها، سینه', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. توپ تعادلی را با دو دست بگیرید و نزدیک سینه در آغوش بگیرید.
۳. عضلات میان‌تنه را درگیر کنید و آرام به عقب متمایل شوید و کمر را صاف و پاها را روی زمین نگه دارید.
۴. تا جایی به عقب بروید که کشش را در عضلات پشت حس کنید.
۵. وضعیت را چند ثانیه نگه دارید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1338.gif', 'lower-back', 'deltoids,chest', '1. Sit on the stability ball with your feet flat on the ground and your back straight.
2. Hold the stability ball with both hands, hugging it close to your chest.
3. Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.
4. Continue leaning back until you feel a stretch in your back muscles.
5. Hold the position for a few seconds, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '1338') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1339', 'کشش زیربغل با توپ تعادلی', 'Exercise ball lat stretch', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'شانه‌ها، پشت بازو', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. یک دمبل را در یک دست بگیرید و دست را صاف بالای سر ببرید.
۳. آرام به طرف مخالف خم شوید تا کشش را در زیربغل حس کنید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس به وضعیت شروع برگردید.
۵. حرکت را برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1339.gif', 'upper-back', 'deltoids,triceps', '1. Sit on a stability ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in one hand and extend your arm straight up overhead.
3. Slowly lean to the opposite side, feeling a stretch in your lat muscle.
4. Hold the stretch for 20-30 seconds, then return to the starting position.
5. Repeat on the other side.', '1339') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1341', 'کشش کمر با توپ تعادلی (هرمی)', 'Exercise ball lower back stretch (pyramid)', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. پاها را آرام جلو ببرید و توپ را زیر کمر بغلتانید تا پایین کمر روی توپ قرار گیرد.
۳. دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.
۴. میان‌تنه را درگیر کنید و بالاتنه را آرام به سمت زمین پایین ببرید تا پایین کمر روی توپ کشیده شود.
۵. کشش را چند ثانیه نگه دارید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1341.gif', 'upper-back', 'gluteal,hamstring', '1. Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.
3. Place your hands behind your head or cross them over your chest.
4. Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.
5. Hold the stretch for a few seconds, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '1341') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1342', 'کشش زیربغل خوابیده به پهلو روی توپ تعادلی', 'Exercise ball lying side lat stretch', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'شانه‌ها، پشت بازو', '۱. به پهلو دراز بکشید، پاها صاف و سر روی توپ تعادلی باشد.
۲. برای ثبات دست بالایی را روی توپ بگذارید.
۳. دست بالایی را بالای سر ببرید و اجازه دهید تنه کمی بچرخد.
۴. کشش را در عضلات زیربغل در پهلوی بدن حس کنید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس طرف را عوض کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1342.gif', 'upper-back', 'deltoids,triceps', '1. Lie on your side with your legs extended and your head supported by the stability ball.
2. Place your top arm on the ball for stability.
3. Reach your top arm overhead and allow your torso to rotate slightly.
4. Feel the stretch in your lat muscles on the side of your body.
5. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '1342') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1382', 'ساق پا با توپ تعادلی روی دیوار', 'Exercise ball on the wall calf raise', 'legs', 'پا', 'dumbbell', 'دمبل', 'ساق پا', 'همسترینگ (پشت ران)، چهارسر ران', '۱. پشت به دیوار بایستید و یک توپ تعادلی بین پایین کمر و دیوار قرار دهید.
۲. پاها را به اندازه عرض شانه باز کنید و پنجه‌ها رو به جلو باشد.
۳. در هر دست یک دمبل بگیرید و دست‌ها را کنار بدن صاف نگه دارید.
۴. پاشنه‌ها را از زمین بلند کنید و وزن بدن را روی پنجه پاها ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1382.gif', 'calves', 'hamstring,quadriceps', '1. Stand with your back against a wall and place an exercise ball between your lower back and the wall.
2. Position your feet shoulder-width apart, with your toes pointing forward.
3. Hold a dumbbell in each hand, with your arms extended by your sides.
4. Raise your heels off the ground, lifting your body weight onto the balls of your feet.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '1382') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3241', 'ساق پا با توپ تعادلی روی دیوار (توپ تنیس بین مچ‌ها)', 'Exercise ball on the wall calf raise (tennis ball between ankles)', 'legs', 'پا', 'dumbbell', 'دمبل', 'ساق پا', 'همسترینگ (پشت ران)، چهارسر ران', '۱. رو به دیوار بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. یک توپ تعادلی بین دیوار و پایین کمر قرار دهید.
۳. در هر دست یک دمبل بگیرید و دست‌ها را کنار بدن صاف نگه دارید.
۴. یک توپ تنیس بین مچ پاها بگذارید.
۵. پاشنه‌ها را از زمین بلند کنید و بدن را روی پنجه پاها ببرید.
۶. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3241.gif', 'calves', 'hamstring,quadriceps', '1. Stand facing a wall with your feet shoulder-width apart.
2. Place an exercise ball between the wall and your lower back.
3. Hold a dumbbell in each hand, with your arms extended by your sides.
4. Place a tennis ball between your ankles.
5. Raise your heels off the ground, lifting your body up onto your toes.
6. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '3241') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3240', 'ساق پا با توپ تعادلی روی دیوار (توپ تنیس بین زانوها)', 'Exercise ball on the wall calf raise (tennis ball between knees)', 'legs', 'پا', 'dumbbell', 'دمبل', 'ساق پا', 'چهارسر ران، همسترینگ (پشت ران)', '۱. پشت به دیوار بایستید و یک توپ تعادلی بین پایین کمر و دیوار قرار دهید.
۲. پاها را به اندازه عرض شانه و کمی جلوتر از بدن قرار دهید.
۳. در هر دست یک دمبل بگیرید و دست‌ها را کنار بدن صاف نگه دارید.
۴. یک توپ تنیس بین زانوها بگذارید.
۵. پاشنه‌ها را از زمین بلند کنید و بدن را روی پنجه پاها ببرید.
۶. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3240.gif', 'calves', 'quadriceps,hamstring', '1. Stand with your back against a wall and place an exercise ball between your lower back and the wall.
2. Position your feet shoulder-width apart and slightly in front of you.
3. Hold a dumbbell in each hand, with your arms extended by your sides.
4. Place a tennis ball between your knees.
5. Raise your heels off the ground, lifting your body up onto your toes.
6. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '3240') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1416', 'چرخش پایین‌تنه دمر تک‌پا روی توپ تعادلی', 'Exercise ball one leg prone lower body rotation', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، میان‌تنه', '۱. دمر روی توپ تعادلی دراز بکشید، لگن روی توپ و پاها صاف پشت سر باشد.
۲. برای حمایت دست‌ها را جلوی خود روی زمین بگذارید.
۳. برای ثبات بدن باسن و میان‌تنه را درگیر کنید.
۴. یک پا را آرام از زمین بلند کنید و صاف و موازی زمین نگه دارید.
۵. پا را به بیرون و دور از بدن بچرخانید و لگن و بالاتنه را ثابت نگه دارید.
۶. لحظه‌ای در انتهای چرخش مکث کنید، سپس پا را آرام به وضعیت شروع برگردانید.
۷. چرخش را با پای دیگر تکرار کنید.
۸. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1416.gif', 'gluteal', 'hamstring,quadriceps,abs', '1. Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.
2. Place your hands on the ground in front of you for support.
3. Engage your glutes and core muscles to stabilize your body.
4. Slowly lift one leg off the ground, keeping it straight and parallel to the floor.
5. Rotate your leg outward, away from your body, while keeping your hips and upper body stable.
6. Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.
7. Repeat the rotation with the other leg.
8. Continue alternating legs for the desired number of repetitions.', '1416') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1417', 'پشت پا با ضربه مورب تک‌پا روی توپ تعادلی', 'Exercise ball one legged diagonal kick hamstring curl', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، ساق پا', '۱. به پشت دراز بکشید، پاها صاف و پاشنه‌ها روی توپ تعادلی باشد.
۲. برای ثبات دست‌ها را کنار بدن بگذارید.
۳. باسن و میان‌تنه را درگیر کنید و لگن را از زمین بلند کنید تا بدن از شانه تا پاشنه یک خط صاف بسازد.
۴. زانوی راست را خم کنید و به سمت سینه بیاورید و پای چپ را صاف و پنجه را بالا کشیده نگه دارید.
۵. پای راست را به صورت مورب از جلوی بدن ضربه بزنید، کاملاً صاف کنید و همسترینگ را درگیر کنید.
۶. پای راست را آرام و با کنترل و ثبات به وضعیت شروع برگردانید.
۷. حرکت را با پای چپ تکرار کنید و به تعداد تکرار دلخواه طرفین را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1417.gif', 'gluteal', 'hamstring,calves', '1. Start by lying on your back with your legs extended and your heels resting on top of the stability ball.
2. Place your arms by your sides for stability.
3. Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.
4. Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.
5. Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.
6. Slowly return your right leg to the starting position, maintaining control and stability.
7. Repeat the movement with your left leg, alternating sides for the desired number of repetitions.', '1417') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1296', 'شنا سوئدی پایک روی توپ تعادلی', 'Exercise ball pike push up', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'شانه‌ها، پشت بازو، میان‌تنه', '۱. در وضعیت شنا قرار بگیرید، دست‌ها روی زمین و ساق پاها روی توپ تعادلی باشد.
۲. میان‌تنه را درگیر کنید و لگن را به سمت سقف بالا ببرید و توپ را به سمت دست‌ها بغلتانید.
۳. پاها را صاف و بدن را در حالت پایک نگه دارید تا شکل V وارونه بسازد.
۴. آرنج‌ها را خم کنید و بالاتنه را به سمت زمین پایین ببرید و سر را در راستای دست‌ها نگه دارید.
۵. با فشار دست‌ها و صاف کردن آن‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1296.gif', 'chest', 'deltoids,triceps,abs', '1. Start in a push-up position with your hands on the floor and your shins resting on the stability ball.
2. Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.
3. Keep your legs straight and your body in a pike position, forming an inverted V shape.
4. Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.
5. Push through your hands and extend your arms to return to the starting position.
6. Repeat for the desired number of repetitions.', '1296') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1343', 'بالا آوردن پا دمر روی توپ تعادلی', 'Exercise ball prone leg raise', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'شکم، سرینی (باسن)', '۱. روی تشک دمر دراز بکشید، پاها صاف و پنجه‌ها روی توپ تعادلی باشد.
۲. دست‌ها را به اندازه عرض شانه روی زمین بگذارید و عضلات میان‌تنه را درگیر کنید.
۳. با پاهای صاف، آن‌ها را آرام از زمین بلند کنید و با کمک کمر و باسن تا جای ممکن بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1343.gif', 'lower-back', 'abs,gluteal', '1. Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.
2. Place your hands on the ground, shoulder-width apart, and engage your core muscles.
3. Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '1343') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1560', 'کشش همسترینگ نشسته روی توپ تعادلی', 'Exercise ball seated hamstring stretch', 'legs', 'پا', 'other', 'سایر', 'همسترینگ (پشت ران)', 'سرینی (باسن)، پایین کمر', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. توپ را آرام به جلو بغلتانید و پاها را جلو ببرید تا بالای کمر روی توپ و پاها صاف جلوی بدن باشد.
۳. برای حمایت دست‌ها را روی لگن بگذارید.
۴. میان‌تنه را درگیر کنید و بالاتنه را آرام به سمت زمین پایین ببرید و کمر را صاف و سینه را بالا نگه دارید.
۵. وقتی کشش را در همسترینگ حس کردید متوقف شوید و وضعیت را ۲۰ تا ۳۰ ثانیه نگه دارید.
۶. با فشار پاشنه‌ها و کمک همسترینگ آرام به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1560.gif', 'hamstring', 'gluteal,lower-back', '1. Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.
3. Place your hands on your hips for support.
4. Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.
5. Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.
6. Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.
7. Repeat for the desired number of repetitions.', '1560') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1745', 'کشش پشت بازو نشسته روی توپ تعادلی', 'Exercise ball seated triceps stretch', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. یک دمبل را در یک دست بگیرید و دست را صاف بالای سر ببرید.
۳. آرنج را خم کنید و دمبل را پشت سر پایین ببرید و بازو را نزدیک گوش نگه دارید.
۴. کشش را چند ثانیه نگه دارید، سپس به وضعیت شروع برگردید.
۵. با دست دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1745.gif', 'triceps', 'deltoids', '1. Sit on a stability ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in one hand and extend your arm straight up above your head.
3. Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.
4. Hold the stretch for a few seconds, then return to the starting position.
5. Repeat with the other arm.', '1745') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1746', 'پشت بازو طاق‌باز روی توپ تعادلی', 'Exercise ball supine triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'پشت بازو', 'شانه‌ها', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. یک دمبل را با دو دست بگیرید و دست‌ها را صاف به سمت سقف ببرید.
۳. دمبل را آرام پشت سر پایین ببرید و آرنج‌ها را نزدیک گوش‌ها نگه دارید.
۴. لحظه‌ای مکث کنید، سپس دمبل را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1746.gif', 'triceps', 'deltoids', '1. Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.
3. Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.
4. Pause for a moment, then raise the dumbbell back up to the starting position.
5. Repeat for the desired number of repetitions.', '1746') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1747', 'پرس فرانسوی میله EZ روی توپ تعادلی', 'Ez bar french press on exercise ball', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. روی توپ تعادلی بنشینید و میله EZ را از رو بگیرید.
۲. دست‌ها را صاف بالا ببرید و آرنج‌ها را نزدیک سر نگه دارید.
۳. با خم کردن آرنج‌ها میله را آرام پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1747.gif', 'triceps', 'deltoids', '1. Sit on an exercise ball and hold an EZ barbell with an overhand grip.
2. Extend your arms straight up, keeping your elbows close to your head.
3. Slowly lower the barbell behind your head by bending your elbows.
4. Pause for a moment, then extend your arms back up to the starting position.
5. Repeat for the desired number of repetitions.', '1747') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3010', 'پول‌اور آرنج خم خوابیده میله EZ', 'Ez bar lying bent arms pullover', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'پشت بازو، سینه', '۱. روی نیمکت صاف دراز بکشید؛ سر در یک انتهای نیمکت و پاها روی زمین.
۲. میله EZ را از رو (کف دست رو به جلو) و به اندازه عرض شانه بگیرید.
۳. دست‌ها را صاف بالای سینه ببرید و آرنج‌ها را کمی خم نگه دارید.
۴. میله را در مسیری کمانی پشت سر پایین ببرید و خم آرنج‌ها را حفظ کنید.
۵. لحظه‌ای مکث کنید، سپس با معکوس کردن مسیر کمانی میله را به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3010.gif', 'upper-back', 'triceps,chest', '1. Lie flat on a bench with your head at one end and your feet on the floor.
2. Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.
3. Extend your arms straight above your chest, keeping a slight bend in your elbows.
4. Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.
5. Pause for a moment, then return the barbell to the starting position by reversing the arc motion.
6. Repeat for the desired number of repetitions.', '3010') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1748', 'پشت بازو دست جمع خوابیده پشت سر میله EZ', 'Ez bar lying close grip triceps extension behind head', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و سر در انتهای نیمکت باشد.
۲. میله EZ را با دست‌های جمع و کف دست رو به بالا بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها هالتر را آرام به پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1748.gif', 'triceps', 'deltoids', '1. Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
2. Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.
3. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.
4. Pause for a moment, then extend your arms back up to the starting position.
5. Repeat for the desired number of repetitions.', '1748') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1344', 'زیربغل خم دست‌برعکس میله EZ', 'Ez bar reverse grip bent over row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. میله EZ را از زیر با کف دست رو به بالا و دست‌ها به اندازه عرض شانه بگیرید.
۳. از لگن به جلو خم شوید، کمر را صاف و سینه را بالا نگه دارید تا تنه تقریباً موازی زمین شود.
۴. میله EZ را به سمت پایین سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در بالا مکث کنید، سپس میله را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1344.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.
3. Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.
4. Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '1344') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1682', 'جلو بازو تمرکزی دست جمع نشسته میله EZ', 'Ez bar seated close grip concentration curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و میله EZ را از زیر بگیرید.
۲. آرنج را روی داخل ران، کمی بالاتر از زانو تکیه دهید.
۳. میله را به سمت شانه بالا بیاورید و بازو را ثابت نگه دارید.
۴. در اوج حرکت جلو بازو را منقبض کنید، سپس میله را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1682.gif', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.
2. Rest your elbow on the inside of your thigh, just above the knee.
3. Curl the barbell up towards your shoulder while keeping your upper arm stationary.
4. Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '1682') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1749', 'پرس فرانسوی ایستاده میله EZ', 'Ez bar standing french press', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از رو بگیرید.
۲. میله را بالای سر ببرید و دست‌ها را کاملاً صاف کنید.
۳. بازوها را نزدیک سر نگه دارید و با خم کردن آرنج‌ها هالتر را آرام پشت سر پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1749.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.
2. Raise the barbell above your head, fully extending your arms.
3. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.
4. Pause for a moment, then extend your arms back to the starting position.
5. Repeat for the desired number of repetitions.', '1749') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0445', 'پرس ضد جاذبه میله EZ', 'Ez barbell anti gravity press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، سینه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از رو بگیرید.
۲. میله را تا ارتفاع شانه بالا بیاورید، آرنج‌ها کمی خم و کف دست‌ها رو به جلو باشد.
۳. هالتر را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۴. هالتر را تا ارتفاع شانه پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0445.gif', 'deltoids', 'triceps,chest', '1. Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.
2. Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.
3. Press the barbell overhead, extending your arms fully.
4. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', '0445') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1627', 'جلو بازو لاری دست جمع میله EZ', 'Ez barbell close grip preacher curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. روی نیمکت لاری بنشینید، بازوها را روی پد بگذارید و میله EZ را از زیر بگیرید.
۲. پشت بازوها را روی پد بگذارید و دست‌ها را کاملاً صاف کنید و کمر را صاف نگه دارید.
۳. میله را آرام به سمت شانه‌ها بالا بیاورید و جلو بازو را منقبض کنید.
۴. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۵. میله را به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1627.gif', 'biceps', 'forearm', '1. Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.
2. Rest your triceps on the pad and fully extend your arms, keeping your back straight.
3. Slowly curl the barbell towards your shoulders, contracting your biceps.
4. Pause for a moment at the top, squeezing your biceps.
5. Lower the barbell back to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '1627') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0446', 'جلو بازو دست جمع میله EZ', 'Ez barbell close-grip curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از زیر و به اندازه عرض شانه بگیرید.
۲. در تمام حرکت آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.
۳. میله را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0446.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.
2. Keep your elbows close to your torso and your upper arms stationary throughout the movement.
3. Curl the barbell up towards your shoulders, contracting your biceps.
4. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0446') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0448', 'پرس صورت دست جمع روی نیمکت زیرسینه میله EZ', 'Ez barbell decline close grip face press', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت زیرسینه دراز بکشید و سر پایین‌تر از پاها باشد.
۲. میله EZ را با دست‌های جمع و کف دست‌های رو به هم بگیرید.
۳. دست‌ها را صاف بالای سینه ببرید و آرنج‌ها را نزدیک بدن نگه دارید.
۴. با خم کردن آرنج‌ها میله را به سمت پیشانی پایین بیاورید.
۵. لحظه‌ای مکث کنید، سپس میله را به وضعیت شروع پرس کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0448.gif', 'triceps', 'chest,deltoids', '1. Lie on a decline bench with your head lower than your feet.
2. Grasp the ez barbell with a close grip, palms facing each other.
3. Extend your arms straight up above your chest, keeping your elbows close to your body.
4. Lower the barbell towards your forehead by bending your elbows.
5. Pause for a moment, then press the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '0448') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2186', 'پشت بازو روی نیمکت زیرسینه میله EZ', 'Ez barbell decline triceps extension', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت زیرسینه دراز بکشید، سر پایین‌تر از پاها و پاها محکم باشد.
۲. میله EZ را از رو و به اندازه عرض شانه بگیرید.
۳. دست‌ها را کاملاً صاف کنید و آرنج‌ها را نزدیک سر نگه دارید.
۴. با خم کردن آرنج‌ها میله را آرام به سمت پیشانی پایین بیاورید.
۵. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2186.gif', 'triceps', 'deltoids', '1. Lie on a decline bench with your head lower than your feet and your feet secured.
2. Hold the ez barbell with an overhand grip, hands shoulder-width apart.
3. Extend your arms fully, keeping your elbows close to your head.
4. Lower the barbell slowly towards your forehead, bending your elbows.
5. Pause for a moment, then extend your arms back to the starting position.
6. Repeat for the desired number of repetitions.', '2186') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0449', 'پشت بازو روی نیمکت شیب‌دار میله EZ', 'Ez barbell incline triceps extension', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت بنشینید، کمر به پد تکیه داشته باشد و میله EZ را از رو بگیرید.
۳. دست‌ها را کاملاً بالای سر صاف کنید و آرنج‌ها را نزدیک سر نگه دارید.
۴. با خم کردن آرنج‌ها میله را پشت سر پایین ببرید و بازوها را ثابت نگه دارید.
۵. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0449.gif', 'triceps', 'deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.
3. Extend your arms fully overhead, keeping your elbows close to your head.
4. Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.
5. Pause for a moment, then extend your arms back to the starting position.
6. Repeat for the desired number of repetitions.', '0449') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0450', 'پرس سینه جی‌ام میله EZ', 'Ez barbell jm bench press', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. میله EZ را از رو و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را تا سینه پایین بیاورید و آرنج‌ها را جمع و نزدیک بدن نگه دارید.
۴. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0450.gif', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lower the barbell to your chest, keeping your elbows tucked in close to your body.
4. Push the barbell back up to the starting position, fully extending your arms.
5. Repeat for the desired number of repetitions.', '0450') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0451', 'جلو بازو دست‌برعکس میله EZ', 'Ez barbell reverse grip curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از زیر بگیرید.
۲. در طول تمرین آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.
۳. با بازدم و انقباض جلو بازو میله را بالا بیاورید.
۴. هالتر را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و هالتر در سطح شانه باشد.
۵. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۶. با دم، میله را آرام به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0451.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.
2. Keep your elbows close to your torso and your upper arms stationary throughout the exercise.
3. Curl the barbell upwards by contracting your biceps, while exhaling.
4. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Slowly begin to bring the barbell back to the starting position as you inhale.
7. Repeat for the desired number of repetitions.', '0451') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0452', 'جلو بازو لاری دست‌برعکس میله EZ', 'Ez barbell reverse grip preacher curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. روی نیمکت لاری بنشینید، سینه روی پد و کف پاها روی زمین باشد.
۲. میله EZ را از زیر و به اندازه عرض شانه بگیرید.
۳. بازوها را روی پد بگذارید و اجازه دهید ساعدها آویزان باشند.
۴. بازوها را ثابت نگه دارید و با بازدم میله را به سمت شانه‌ها بالا بیاورید.
۵. لحظه‌ای در بالا مکث کنید، سپس با دم هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0452.gif', 'biceps', 'forearm', '1. Sit on a preacher bench with your chest against the pad and your feet flat on the floor.
2. Grasp the ez barbell with an underhand grip, hands shoulder-width apart.
3. Rest your upper arms on the pad, allowing your forearms to hang down.
4. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.
5. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '0452') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1458', 'جلو بازو نشسته میله EZ', 'Ez barbell seated curls', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. روی نیمکت بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. میله EZ را از زیر با کف دست رو به بالا و دست‌ها به اندازه عرض شانه بگیرید.
۳. بازوها را روی ران‌ها بگذارید و اجازه دهید میله جلوی بدن آویزان باشد.
۴. بازوها را ثابت نگه دارید و با بازدم میله EZ را به سمت شانه‌ها بالا بیاورید.
۵. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۶. با دم، میله EZ را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1458.gif', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the ground and your back straight.
2. Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.
3. Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.
4. Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.
5. Pause for a moment at the top, squeezing your biceps.
6. Inhale and slowly lower the ez barbell back to the starting position.
7. Repeat for the desired number of repetitions.', '1458') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0453', 'پشت بازو نشسته میله EZ', 'Ez barbell seated triceps extension', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. میله EZ را از رو و به اندازه عرض شانه بگیرید.
۳. هالتر را بالای سر ببرید و دست‌ها را کاملاً صاف کنید.
۴. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها میله را پشت سر پایین ببرید.
۵. لحظه‌ای مکث کنید، سپس با صاف کردن دست‌ها هالتر را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0453.gif', 'triceps', 'deltoids', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold the ez barbell with an overhand grip, hands shoulder-width apart.
3. Raise the barbell overhead, fully extending your arms.
4. Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.
5. Pause for a moment, then raise the barbell back to the starting position by extending your arms.
6. Repeat for the desired number of repetitions.', '0453') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0454', 'جلو بازو عنکبوتی میله EZ', 'Ez barbell spider curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از زیر با کف دست رو به بالا بگیرید.
۲. بازوها را روی نیمکت لاری یا توپ تعادلی بگذارید و اجازه دهید آرنج‌ها آویزان باشند.
۳. بازوها را ثابت نگه دارید و با بازدم میله را به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0454.gif', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.
2. Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.
3. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0454') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1628', 'جلو بازو عنکبوتی میله EZ (نسخه ۲)', 'Ez barbell spider curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از زیر با کف دست رو به بالا بگیرید.
۲. بازوها را روی نیمکت لاری یا توپ تعادلی بگذارید و اجازه دهید آرنج‌ها آویزان باشند.
۳. بازوها را ثابت نگه دارید و با بازدم میله را به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1628.gif', 'biceps', 'forearm', '1. Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.
2. Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.
3. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '1628') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2404', 'جلو بازو میله EZ با آرم‌بلستر', 'Ez-bar biceps curl (with arm blaster)', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از زیر با کف دست رو به بالا بگیرید.
۲. بازوها را به آرم‌بلستر تکیه دهید و در طول تمرین ثابت نگه دارید.
۳. آرنج‌ها را نزدیک بدن نگه دارید و با بازدم میله را به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، هالتر را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2404.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.
2. Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.
3. Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.
4. Pause for a moment at the top, squeezing your biceps.
5. Inhale and slowly lower the barbell back to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '2404') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2432', 'پرس سینه دست جمع میله EZ', 'Ez-bar close-grip bench press', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و کمر به نیمکت چسبیده باشد.
۲. میله EZ را با دست‌های جمع، به اندازه عرض شانه و کف دست رو به جلو بگیرید.
۳. هالتر را از جایگاه بردارید و با دست‌های کاملاً صاف درست بالای سینه نگه دارید.
۴. هالتر را آرام به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید.
۶. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2432.gif', 'triceps', 'chest,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
2. Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.
3. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.
4. Slowly lower the barbell towards your chest, keeping your elbows close to your body.
5. Pause for a moment when the barbell touches your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '2432') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2741', 'جلو بازو دست باز ایستاده میله EZ', 'Ez-barbell standing wide grip biceps curl', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و میله EZ را از زیر و بازتر از عرض شانه بگیرید.
۲. در تمام حرکت آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.
۳. میله را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2741.gif', 'biceps', 'forearm', '1. Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.
2. Keep your elbows close to your torso and your upper arms stationary throughout the movement.
3. Curl the barbell up towards your shoulders by contracting your biceps.
4. Pause for a moment at the top, then slowly lower the barbell back to the starting position.
5. Repeat for the desired number of repetitions.', '2741') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2133', 'راه رفتن کشاورز', 'Farmers walk', 'legs', 'پا', 'dumbbell', 'دمبل', 'چهارسر ران', 'ساق پا، ساعد، میان‌تنه', '۱. صاف بایستید و در هر دست یک دمبل با کف دست رو به پهلوها بگیرید.
۲. کمر را صاف و شانه‌ها را عقب نگه دارید.
۳. با حفظ بدن صاف، گام‌های کوتاه و کنترل‌شده به جلو بردارید.
۴. برای مسافت یا زمان دلخواه به راه رفتن ادامه دهید.
۵. برای پایان، راه رفتن را متوقف کنید و دمبل‌ها را با احتیاط کنار بدن پایین بگذارید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2133.gif', 'quadriceps', 'calves,forearm,abs', '1. Stand up straight with a dumbbell in each hand, palms facing your sides.
2. Keep your back straight and your shoulders back.
3. Take small, controlled steps forward, maintaining an upright posture.
4. Continue walking for the desired distance or time.
5. To finish, stop walking and carefully lower the dumbbells to your sides.', '2133') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0455', 'جلو بازو انگشت', 'Finger curls', 'arms', 'بازو', 'barbell', 'هالتر', 'ساعد', 'خم‌کننده‌های مچ، عضلات پنجه', '۱. روی نیمکت بنشینید، کف پاها روی زمین باشد و هالتر را از زیر با کف دست رو به بالا بگیرید.
۲. ساعدها را روی ران‌ها بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.
۳. انگشتان را آرام به سمت کف دست جمع کنید و هالتر را محکم بفشارید.
۴. انقباض را لحظه‌ای نگه دارید، سپس انگشتان را آرام به وضعیت شروع باز کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0455.gif', 'forearm', '', '1. Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.
2. Rest your forearms on your thighs, allowing your wrists to hang off the edge.
3. Slowly curl your fingers towards your palms, squeezing the barbell tightly.
4. Hold the contraction for a moment, then slowly release your fingers back to the starting position.
5. Repeat for the desired number of repetitions.', '0455') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3303', 'پرچم انسانی', 'Flag', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، شانه‌ها', '۱. یک میله عمودی را با دو دست، کف دست‌های رو به هم و دست‌های کاملاً صاف بگیرید.
۲. میان‌تنه را درگیر کنید و پاها را صاف از زمین بلند کنید.
۳. با قدرت میان‌تنه و بالاتنه پاها را بالا بیاورید تا موازی زمین شوند.
۴. این وضعیت را تا جای ممکن نگه دارید و بدن را در یک خط صاف حفظ کنید.
۵. پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3303.gif', 'abs', 'obliques,deltoids', '1. Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.
2. Engage your core and lift your legs off the ground, keeping them straight.
3. Using your core and upper body strength, raise your legs until they are parallel to the ground.
4. Hold this position for as long as you can, maintaining a straight body line.
5. Slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '3303') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0456', 'دراز و نشست با زانوی خم', 'Flexion leg sit up (bent knee)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. همزمان پاها را از زمین بلند کنید، زانوها را خم کنید و به سمت سینه بیاورید.
۵. لحظه‌ای در بالا مکث کنید، سپس بالاتنه و پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0456.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.
5. Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '0456') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0457', 'دراز و نشست با دست صاف', 'Flexion leg sit up (straight arm)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، چهارسر ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها صاف بالای سر باشد.
۲. با درگیر کردن شکم، بالاتنه را از زمین بلند کنید و همزمان پاها را به سمت سینه بیاورید.
۳. هنگام بلند کردن بالاتنه و پاها، دست‌ها را به سمت پنجه پاها ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه و پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0457.gif', 'abs', 'hip-flexors,quadriceps', '1. Lie flat on your back with your legs extended and arms straight above your head.
2. Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.
3. Reach your hands towards your toes as you lift your upper body and legs.
4. Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0457') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0458', 'قفسه روی زمین (با هالتر)', 'Floor fly (with barbell)', 'chest', 'سینه', 'barbell', 'هالتر', 'سینه', 'سرشانه، پشت بازو', '۱. به پشت صاف روی زمین دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. هالتر را از رو بگیرید و دست‌ها را صاف بالای سینه نگه دارید.
۳. هالتر را آرام به طرفین پایین بیاورید و آرنج‌ها را کمی خم نگه دارید.
۴. هالتر را تا جایی پایین بیاورید که دست‌ها موازی زمین شوند و کشش را در سینه حس کنید.
۵. لحظه‌ای مکث کنید، سپس با انقباض عضلات سینه هالتر را به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0458.gif', 'chest', 'deltoids,triceps', '1. Lie flat on your back on the floor with your knees bent and feet flat on the ground.
2. Hold a barbell with an overhand grip, arms extended straight up over your chest.
3. Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.
4. Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.
5. Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0458') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0459', 'ضربات قیچی پا', 'Flutter kicks', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'خم‌کننده ران، پایین شکم', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها کنار بدن باشد.
۲. میان‌تنه را درگیر کنید و پاها را حدود ۱۵ سانتی‌متر از زمین بلند کنید.
۳. با پاهای صاف، به نوبت یک پا را کمی بالاتر از پای دیگر ببرید.
۴. این حرکت قیچی را به تعداد تکرار دلخواه ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0459.gif', 'gluteal', 'hip-flexors,abs', '1. Lie flat on your back with your legs extended and your hands by your sides.
2. Engage your core and lift your legs off the ground about 6 inches.
3. Keeping your legs straight, alternate lifting one leg slightly higher than the other.
4. Continue this fluttering motion for the desired number of repetitions.', '0459') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1472', 'پرش به جلو', 'Forward jump', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'ساق پا، همسترینگ (پشت ران)، سرینی (باسن)', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. زانوها را خم کنید و به حالت اسکوات پایین بروید.
۳. برای گرفتن شتاب دست‌ها را به عقب تاب دهید.
۴. با باز کردن لگن، زانوها و مچ پاها به صورت انفجاری به جلو بپرید.
۵. نرم روی پنجه پاها فرود بیایید و بلافاصله پرش بعدی را انجام دهید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1472.gif', 'quadriceps', 'calves,hamstring,gluteal', '1. Stand with your feet shoulder-width apart.
2. Bend your knees and lower your body into a squat position.
3. Swing your arms back for momentum.
4. Jump forward explosively, extending your hips, knees, and ankles.
5. Land softly on the balls of your feet and immediately go into the next jump.
6. Repeat for the desired number of repetitions.', '1472') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3470', 'لانج جلو', 'Forward lunge (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و دست‌ها را روی لگن بگذارید.
۲. با پای راست یک گام بلند به جلو بردارید و به حالت لانج پایین بروید.
۳. زانوی راست را حدود ۹۰ درجه خم کنید و زانو را در راستای مچ پا نگه دارید.
۴. با فشار پای راست به وضعیت شروع برگردید.
۵. با پای چپ تکرار کنید و به تعداد تکرار دلخواه طرفین را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3470.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet hip-width apart and hands on your hips.
2. Take a big step forward with your right foot, lowering your body into a lunge position.
3. Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.
4. Push off with your right foot and return to the starting position.
5. Repeat with your left leg, alternating sides for the desired number of repetitions.', '3470') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3194', 'اسکوات فرانکنشتاین', 'Frankenstein squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را با دست‌های صاف جلوی بدن نگه دارید.
۲. با کمر صاف، با خم کردن زانوها و لگن مانند نشستن روی صندلی پایین بروید.
۳. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۴. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3194.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.
2. Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.
3. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
4. Pause for a moment, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '3194') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2429', 'کرانچ قورباغه‌ای', 'Frog crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن شکم، بالاتنه را از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2429.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '2429') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3301', 'پلانچ قورباغه‌ای', 'Frog planche', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، سینه، پشت بازو', '۱. در وضعیت شنا قرار بگیرید، دست‌ها به اندازه عرض شانه و پاها جفت باشد.
۲. آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید و کمر را صاف نگه دارید.
۳. هنگام پایین رفتن، پاها را از زمین بلند کنید و زانوها را به سمت سینه بیاورید.
۴. این وضعیت را چند ثانیه نگه دارید، سپس پاها را باز کنید و خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3301.gif', 'abs', 'deltoids,chest,triceps', '1. Start in a push-up position with your hands shoulder-width apart and your feet together.
2. Bend your elbows and lower your body towards the ground, keeping your back straight.
3. As you lower your body, lift your feet off the ground and bring your knees towards your chest.
4. Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '3301') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3296', 'فرانت لیور', 'Front lever', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'زیربغل، شانه‌ها، ساعد', '۱. از میله بارفیکس با دست‌های از رو و به اندازه عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و کتف‌ها را به پایین و عقب بکشید.
۳. زانوها را خم کنید و به سمت سینه جمع کنید.
۴. همزمان پاها را بالا بیاورید و صاف جلوی بدن دراز کنید و بدن را موازی زمین نگه دارید.
۵. این وضعیت را تا جای ممکن نگه دارید و هدف را رسیدن به فرانت لیور کامل قرار دهید.
۶. برای پایان، پاها را آرام پایین بیاورید و به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3296.gif', 'abs', 'upper-back,deltoids,forearm', '1. Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.
2. Engage your core and pull your shoulder blades down and back.
3. Bend your knees and tuck them towards your chest.
4. Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.
5. Hold this position for as long as you can, aiming for a full front lever position.
6. To release, slowly lower your legs back down and return to the starting position.
7. Repeat for the desired number of repetitions.', '3296') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3295', 'تکرار فرانت لیور', 'Front lever reps', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'میان‌تنه، شانه‌ها', '۱. از میله بارفیکس با دست‌های از رو و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و کتف‌ها را به پایین و عقب بکشید.
۳. با بدن صاف، پاها را بالا بیاورید تا موازی زمین شوند.
۴. این وضعیت را تا جای ممکن، ترجیحاً ۱۰ تا ۲۰ ثانیه، نگه دارید.
۵. پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3295.gif', 'upper-back', 'abs,deltoids', '1. Hang from a pull-up bar with an overhand grip, palms facing away from you.
2. Engage your core and pull your shoulder blades down and back.
3. Keeping your body straight, lift your legs up until they are parallel to the ground.
4. Hold this position for as long as you can, aiming for 10-20 seconds.
5. Slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '3295') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0464', 'پلانک جلو با چرخش', 'Front plank with twist', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها درست زیر شانه‌ها و بدن از سر تا پا در یک خط صاف.
۲. برای حفظ ثبات میان‌تنه و باسن را درگیر کنید.
۳. تنه را به راست بچرخانید و دست راست را بلند کرده و به سمت سقف دراز کنید.
۴. هنگام چرخش لگن و پاها را ثابت نگه دارید.
۵. لحظه‌ای نگه دارید، سپس به وضعیت شروع برگردید.
۶. چرخش را برای سمت چپ تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0464.gif', 'abs', 'obliques,deltoids', '1. Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.
2. Engage your core and glutes to maintain a stable position.
3. Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.
4. Keep your hips and legs stable as you twist.
5. Hold for a moment, then return to the starting position.
6. Repeat the twist on the left side.
7. Continue alternating sides for the desired number of repetitions.', '0464') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3315', 'مالتیز کامل', 'Full maltese', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، سینه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را صاف به طرفین باز کنید.
۲. با دست‌های صاف آرام به جلو متمایل شوید تا بالاتنه موازی زمین شود.
۳. میان‌تنه را درگیر کنید و این وضعیت را چند ثانیه نگه دارید.
۴. با فشار پاها بایستید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3315.gif', 'abs', 'deltoids,chest', '1. Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.
2. Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.
3. Engage your core and hold this position for a few seconds.
4. Return to the starting position by pushing through your feet and standing back up.
5. Repeat for the desired number of repetitions.', '3315') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3299', 'پلانچ کامل', 'Full planche', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، سینه، پشت بازو', '۱. در وضعیت شنا قرار بگیرید، دست‌ها به اندازه عرض شانه و انگشتان رو به جلو باشد.
۲. میان‌تنه را درگیر کنید و وزن را آرام به جلو منتقل کنید و پاها را از زمین بلند کنید.
۳. آن‌قدر وزن را به جلو ببرید که بدن موازی زمین شود و روی دست‌ها تعادل داشته باشید.
۴. این وضعیت را تا جای ممکن نگه دارید و بدن را در یک خط صاف حفظ کنید.
۵. پاها را آرام به زمین برگردانید و به وضعیت شروع بازگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3299.gif', 'abs', 'deltoids,chest,triceps', '1. Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.
2. Engage your core and slowly shift your weight forward, lifting your feet off the ground.
3. Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.
4. Hold this position for as long as you can, maintaining a straight body line.
5. Slowly lower your feet back to the ground and return to the starting position.
6. Repeat for the desired number of repetitions.', '3299') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3327', 'شنا سوئدی پلانچ کامل', 'Full planche push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'شانه‌ها، پشت بازو، میان‌تنه', '۱. در وضعیت شنا قرار بگیرید و دست‌ها را کمی بازتر از عرض شانه بگذارید.
۲. میان‌تنه را درگیر کنید و بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. هنگام پایین رفتن، بدن را به جلو متمایل کنید و پاها را از زمین بلند کنید و روی دست‌ها تعادل بگیرید.
۴. تا جایی پایین بروید که سینه کمی بالاتر از زمین قرار گیرد.
۵. با فشار دست‌ها و صاف کردن آن‌ها بدن را به وضعیت شروع بالا ببرید.
۶. در تمام حرکت بدن را از سر تا پاشنه در یک خط صاف نگه دارید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3327.gif', 'chest', 'deltoids,triceps,abs', '1. Start in a push-up position with your hands placed slightly wider than shoulder-width apart.
2. Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.
3. As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.
4. Continue to lower your body until your chest is just above the ground.
5. Push through your hands and extend your arms to lift your body back up to the starting position.
6. Maintain a straight line from your head to your heels throughout the movement.
7. Repeat for the desired number of repetitions.', '3327') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0466', 'بارفیکس جیروندا تا جناغ', 'Gironda sternum chin', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. رو به یک میله بلند بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دست‌ها را بالا ببرید و میله را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف و بدن صاف از میله آویزان شوید.
۴. زیربغل و جلو بازو را درگیر کنید و با هدایت جناغ، سینه را به سمت میله بالا بکشید.
۵. لحظه‌ای در بالا مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0466.gif', 'upper-back', 'biceps,deltoids', '1. Stand facing a high bar with your feet shoulder-width apart.
2. Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.
3. Hang from the bar with your arms fully extended and your body straight.
4. Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.
5. Pause for a moment at the top, then slowly lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '0466') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3561', 'پل باسن با رژه', 'Glute bridge march', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. باسن را درگیر کنید و لگن را از زمین بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۳. در حالی که لگن بالا است، یک پا را از زمین بلند کنید و زانو را به سمت سینه بیاورید.
۴. پا را به زمین برگردانید و حرکت را با پای دیگر تکرار کنید.
۵. با حفظ حالت پل، پاها را مانند رژه رفتن یکی در میان ادامه دهید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3561.gif', 'gluteal', 'hamstring,quadriceps', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.
3. While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.
4. Lower your foot back to the ground and repeat the movement with the other leg.
5. Continue alternating legs in a marching motion while maintaining the bridge position.
6. Repeat for the desired number of repetitions.', '3561') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3523', 'پل باسن با دو پا روی نیمکت', 'Glute bridge two legs on bench (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، میان‌تنه', '۱. لبه نیمکت بنشینید، کمر به آن تکیه داشته باشد و کف پاها روی زمین باشد.
۲. برای حمایت دست‌ها را کنار لگن روی نیمکت بگذارید.
۳. باسن و همسترینگ را درگیر کنید و لگن را از نیمکت بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3523.gif', 'gluteal', 'hamstring,abs', '1. Sit on the edge of a bench with your back against it and your feet flat on the ground.
2. Place your hands on the bench beside your hips for support.
3. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.
4. Pause for a moment at the top, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions.', '3523') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3193', 'گلوت‌هم ریز', 'Glute-ham raise', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، پایین کمر', '۱. دستگاه گلوت‌هم را متناسب با بدن خود تنظیم کنید.
۲. روی دستگاه دمر قرار بگیرید و مچ پاها را محکم کنید.
۳. دست‌ها را روی سینه بگذارید یا ضربدری کنید.
۴. همسترینگ و باسن را درگیر کنید و بالاتنه را به سمت سقف بالا ببرید.
۵. تا جایی بالا بروید که بدن از سر تا پاشنه در یک خط صاف قرار گیرد.
۶. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3193.gif', 'hamstring', 'gluteal,lower-back', '1. Adjust the glute-ham raise machine to fit your body.
2. Position yourself face down on the machine with your ankles secured.
3. Place your hands on your chest or cross them over your chest.
4. Engage your hamstrings and glutes to lift your upper body up towards the ceiling.
5. Continue lifting until your body is in a straight line from your head to your heels.
6. Pause for a moment at the top, then slowly lower your body back down to the starting position.
7. Repeat for the desired number of repetitions.', '3193') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0467', 'بارفیکس گوریلی', 'Gorilla chin', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'ساعد، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. میله بارفیکس را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف و کف دست رو به جلو از میله آویزان شوید.
۴. میان‌تنه را درگیر کنید و بدن را به سمت میله بالا بکشید تا چانه از میله بالاتر رود.
۵. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0467.gif', 'abs', 'forearm,biceps', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
3. Hang from the bar with your arms fully extended and your palms facing away from you.
4. Engage your core and pull your body up towards the bar, bringing your chin above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0467') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0469', 'کرانچ کشاله ران', 'Groin crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، داخل ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن شکم، پاها را از زمین بلند کنید و زانوها را به سمت سینه بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0469.gif', 'abs', 'hip-flexors,adductors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0469') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1383', 'ساق پا هاک', 'Hack calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. دستگاه را روی وزن مناسب تنظیم کنید.
۲. روی دستگاه بایستید، پنجه‌ها روی سکو و پاشنه‌ها آزاد باشند.
۳. برای ثبات دستگیره‌ها را بگیرید.
۴. با فشار پنجه پاها، پاشنه‌ها را تا جای ممکن بالا ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1383.gif', 'calves', 'hamstring,gluteal', '1. Adjust the sled machine to a comfortable weight.
2. Stand on the sled machine with your toes on the platform and your heels hanging off.
3. Hold onto the handles for stability.
4. Raise your heels as high as possible by pushing through the balls of your feet.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '1383') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1384', 'ساق پا تک‌پا هاک', 'Hack one leg calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. دستگاه را روی وزن مناسب تنظیم کنید.
۲. با یک پا روی دستگاه بایستید و پای دیگر را از زمین جدا نگه دارید.
۳. برای ثبات دستگیره‌ها را بگیرید.
۴. پاشنه را تا جای ممکن بالا ببرید و بدن را روی پنجه پا بلند کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.
۷. پا را عوض کنید و تمرین را تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1384.gif', 'calves', 'hamstring,gluteal', '1. Adjust the sled machine to an appropriate weight.
2. Stand on the sled machine with one foot, keeping the other foot off the ground.
3. Hold onto the handles for stability.
4. Raise your heel as high as possible, lifting your body up on the ball of your foot.
5. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
6. Repeat for the desired number of repetitions.
7. Switch legs and repeat the exercise.', '1384') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3202', 'نیم دراز و نشست', 'Half sit-up (male)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3202.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3202') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1511', 'کشش همسترینگ', 'Hamstring stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. با پای راست یک گام به جلو بردارید و وزن را روی پای راست منتقل کنید.
۳. با کمر صاف، آرام از لگن به جلو خم شوید و با هر دو دست به سمت پای راست بروید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس به وضعیت شروع برگردید.
۵. حرکت را برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1511.gif', 'hamstring', 'gluteal', '1. Stand with your feet shoulder-width apart.
2. Step forward with your right foot and shift your weight onto your right leg.
3. Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.
4. Hold the stretch for 20-30 seconds, then return to the starting position.
5. Repeat on the other side.', '1511') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2139', 'دوچرخه دستی', 'Hands bike', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'پشت بازو، شانه‌ها', '۱. ارتفاع صندلی و دسته را در وضعیت مناسب تنظیم کنید.
۲. روی ارگومتر با کمر صاف بنشینید و پاها روی پدال‌ها باشد.
۳. دستگیره‌ها را بگیرید و دست‌ها را در زاویه ۹۰ درجه قرار دهید.
۴. با دست‌ها شروع به رکاب زدن کنید و دستگیره‌ها را با حرکتی کنترل‌شده هل دهید و بکشید.
۵. برای مدت یا تعداد تکرار دلخواه به رکاب زدن ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2139.gif', 'chest', 'triceps,deltoids', '1. Adjust the seat height and handlebar position to a comfortable level.
2. Sit on the ergometer with your back straight and feet on the pedals.
3. Grasp the handles with your hands and position your arms at a 90-degree angle.
4. Start pedaling with your hands, pushing and pulling the handles in a controlled motion.
5. Continue pedaling for the desired duration or number of repetitions.', '2139') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3218', 'لمس پنجه پا با چرخش دست‌های قفل‌شده', 'Hands clasped circular toe touch (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را جلوی سینه در هم قفل کنید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. دست‌ها را با حرکتی دایره‌ای به سمت پنجه پاها پایین ببرید و بدون فشار بیش از حد تا جای ممکن پیش بروید.
۴. لحظه‌ای در پایین مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3218.gif', 'gluteal', 'hamstring,quadriceps,calves', '1. Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.
4. Pause for a moment at the bottom, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '3218') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3215', 'لمس پنجه پا با چرخش دست‌های قفل‌شده برعکس', 'Hands reversed clasped circular toe touch (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را به طرفین باز کنید.
۲. از کمر به جلو خم شوید و کمر را صاف و زانوها را کمی خم نگه دارید.
۳. دست‌ها را پایین ببرید و پشت پاها در هم قفل کنید.
۴. دست‌ها را آرام با حرکتی دایره‌ای بالا و از روی سر ببرید و پاها را صاف نگه دارید.
۵. حرکت دایره‌ای را تا جایی ادامه دهید که دست‌ها پنجه پاها را لمس کنند.
۶. حرکت را معکوس کنید و دست‌ها را به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3215.gif', 'gluteal', 'hamstring,quadriceps,calves', '1. Stand with your feet shoulder-width apart and your arms extended to the sides.
2. Bend forward at the waist, keeping your back straight and your knees slightly bent.
3. Reach down with your hands and clasp them together behind your legs.
4. Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.
5. Continue the circular motion until your hands touch your toes.
6. Reverse the motion and bring your hands back down to the starting position.
7. Repeat for the desired number of repetitions.', '3215') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3302', 'بالانس روی دست', 'Handstand', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها، میان‌تنه', '۱. فضای باز و کافی برای بالانس روی دست پیدا کنید.
۲. دست‌ها را به اندازه عرض شانه روی زمین بگذارید، انگشتان رو به جلو.
۳. پاها را به سمت دیوار بالا بزنید و با کمک میان‌تنه و شانه‌ها تعادل را حفظ کنید.
۴. در حالت بالانس روی دست، پشت بازو را برای تحمل وزن بدن درگیر کنید.
۵. بالانس را تا جایی که تعادل دارید نگه دارید.
۶. برای پایین آمدن، پاها را آرام به زمین برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3302.gif', 'triceps', 'deltoids,abs', '1. Find an open space with enough room to perform a handstand.
2. Place your hands on the ground shoulder-width apart, fingers pointing forward.
3. Kick your legs up towards the wall, using your core and shoulders to maintain balance.
4. Once in a handstand position, engage your triceps to support your body weight.
5. Hold the handstand for as long as you can maintain balance.
6. To come down, slowly lower your legs back to the ground.
7. Repeat for the desired number of repetitions.', '3302') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0471', 'شنا سوئدی بالانس روی دست', 'Handstand push-up', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها، سینه، میان‌تنه', '۱. پشت به دیوار و با چند قدم فاصله از آن بایستید.
۲. دست‌ها را به اندازه عرض شانه روی زمین بگذارید و پاها را به دیوار بزنید تا در حالت بالانس روی دست قرار بگیرید.
۳. آرنج‌ها را خم کنید و سر را به سمت زمین پایین ببرید و بدن را در یک خط صاف نگه دارید.
۴. با فشار دست‌ها و صاف کردن آن‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0471.gif', 'triceps', 'deltoids,chest,abs', '1. Find a wall and face away from it, standing a few feet away.
2. Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.
3. Bend your elbows and lower your head towards the ground, keeping your body in a straight line.
4. Push through your hands and extend your arms to return to the starting position.
5. Repeat for the desired number of repetitions.', '0471') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1764', 'بالا آوردن پا و لگن در حالت آویزان', 'Hanging leg hip raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و با خم کردن لگن و زانوها پاها را بالا بیاورید تا ران‌ها موازی زمین شوند.
۳. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1764.gif', 'abs', 'hip-flexors,lower-back', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.
3. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
4. Repeat for the desired number of repetitions.', '1764') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1761', 'بالا آوردن زانوی مورب در حالت آویزان', 'Hanging oblique knee raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و زانوها را به سمت سینه بالا بیاورید و همزمان تنه را به طرف بچرخانید.
۳. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۴. برای طرف دیگر تکرار کنید و تنه را در جهت مخالف بچرخانید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1761.gif', 'abs', 'obliques', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.
3. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
4. Repeat on the other side, twisting your torso in the opposite direction.
5. Continue alternating sides for the desired number of repetitions.', '1761') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0473', 'پایک آویزان', 'Hanging pike', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، شانه‌ها', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را صاف به سمت میله بالا بیاورید.
۳. تا جایی بالا بیاورید که بدن شکل «V» بسازد و پاها موازی زمین باشند.
۴. وضعیت را لحظه‌ای نگه دارید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0473.gif', 'abs', 'hip-flexors,deltoids', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your legs up towards the bar, keeping them straight.
3. Continue lifting until your body forms a ''V'' shape, with your legs parallel to the ground.
4. Hold the position for a moment, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0473') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0474', 'بالا آوردن لگن با پای صاف در حالت آویزان', 'Hanging straight leg hip raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را جلوی بدن بالا بیاورید تا موازی زمین شوند.
۳. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0474.gif', 'abs', 'hip-flexors', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your legs up in front of you until they are parallel to the ground.
3. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
4. Repeat for the desired number of repetitions.', '0474') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0475', 'بالا آوردن پای صاف در حالت آویزان', 'Hanging straight leg raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را صاف جلوی بدن بالا بیاورید.
۳. تا جایی بالا بیاورید که پاها موازی زمین شوند یا تا جایی که راحت هستید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0475.gif', 'abs', 'hip-flexors', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your legs up in front of you, keeping them straight.
3. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0475') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0476', 'بالا آوردن لگن با پای صاف و چرخش در حالت آویزان', 'Hanging straight twisting leg hip raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. از میله بارفیکس با دست‌های کاملاً صاف و پاهای صاف آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را صاف به سمت سینه بالا بیاورید.
۳. وقتی پاها موازی زمین شدند، لگن را به یک طرف بچرخانید و پاها را به همان سمت ببرید.
۴. لحظه‌ای مکث کنید، سپس به وضعیت شروع برگردید.
۵. حرکت را تکرار کنید و این بار لگن را به طرف مخالف بچرخانید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0476.gif', 'abs', 'obliques,hip-flexors', '1. Hang from a pull-up bar with your arms fully extended and your legs straight.
2. Engage your core and lift your legs up towards your chest, keeping them straight.
3. Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.
4. Pause for a moment, then return to the starting position.
5. Repeat the movement, but this time twist your hips to the opposite side.
6. Continue alternating sides for the desired number of repetitions.', '0476') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0484', 'بالا آوردن لگن (زانو خم)', 'Hip raise (bent knee)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را کنار بدن با کف دست رو به پایین بگذارید.
۳. میان‌تنه و باسن را درگیر کنید و لگن را از زمین بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0484.gif', 'abs', 'gluteal,hamstring', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands by your sides, palms facing down.
3. Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.
4. Pause for a moment at the top, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions.', '0484') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1418', 'بغل کردن زانو به سینه', 'Hug keens to chest', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. زانوها را خم کنید و به حالت اسکوات پایین بروید.
۳. هنگام پایین رفتن، زانوها را به سمت سینه بیاورید و با دست‌ها در آغوش بگیرید.
۴. این وضعیت را لحظه‌ای نگه دارید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1418.gif', 'gluteal', 'hamstring,quadriceps', '1. Start by standing with your feet shoulder-width apart.
2. Bend your knees and lower your body down into a squat position.
3. As you squat down, bring your knees up towards your chest and hug them with your arms.
4. Hold this position for a moment, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '1418') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3234', 'قفسه هایت دمبل', 'Hyght dumbbell fly', 'chest', 'سینه', 'dumbbell', 'دمبل', 'سینه', 'شانه‌ها', '۱. روی نیمکت صاف دراز بکشید و در هر دست یک دمبل با کف دست‌های رو به هم بگیرید.
۲. دست‌ها را صاف بالای سینه ببرید و آرنج‌ها را کمی خم نگه دارید.
۳. با آرنج‌های کمی خم، دمبل‌ها را در یک کمان باز به طرفین پایین ببرید تا کشش را در سینه حس کنید.
۴. لحظه‌ای مکث کنید، سپس حرکت را معکوس کنید و دمبل‌ها را به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3234.gif', 'chest', 'deltoids', '1. Lie flat on a bench with a dumbbell in each hand, palms facing each other.
2. Extend your arms straight up over your chest, with a slight bend in your elbows.
3. Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.
4. Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '3234') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0488', 'فیله کمر (روی نیمکت)', 'Hyperextension (on bench)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. نیمکت فیله کمر را طوری تنظیم کنید که لگن راحت روی پد قرار گیرد و پاها محکم باشند.
۲. دست‌ها را روی سینه ضربدری کنید یا پشت سر بگذارید.
۳. بالاتنه را آرام به سمت زمین پایین ببرید و کمر را صاف نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس بالاتنه را بالا بیاورید تا با پاها در یک راستا قرار گیرد.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0488.gif', 'lower-back', 'gluteal,hamstring', '1. Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.
2. Cross your arms over your chest or place your hands behind your head.
3. Slowly lower your upper body towards the ground while keeping your back straight.
4. Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.
5. Repeat for the desired number of repetitions.', '0488') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3289', 'دیپ غیرممکن', 'Impossible dips', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. بین دو میله موازی قرار بگیرید، دست‌ها کاملاً صاف و بدن در هوا معلق باشد.
۲. زانوها را خم کنید و مچ پاها را ضربدری کنید.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.
۴. لحظه‌ای مکث کنید، سپس با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3289.gif', 'triceps', 'chest,deltoids', '1. Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.
2. Bend your knees and cross your ankles.
3. Lower your body by bending your elbows until your upper arms are parallel to the ground.
4. Pause for a moment, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '3289') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1471', 'کرم خاکی', 'Inchworm', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، همسترینگ (پشت ران)', '۱. بایستید و پاها را به اندازه عرض لگن باز کنید.
۲. از کمر به جلو خم شوید و دست‌ها را جلوی خود روی زمین بگذارید.
۳. با دست‌ها به جلو راه بروید تا در وضعیت پلانک با دست صاف و بدن در یک خط صاف قرار بگیرید.
۴. لحظه‌ای مکث کنید، سپس با دست‌ها به سمت پاها برگردید و پاها را تا جای ممکن صاف نگه دارید.
۵. وقتی دست‌ها به پاها رسیدند، به وضعیت شروع بایستید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1471.gif', 'abs', 'deltoids,hamstring', '1. Start in a standing position with your feet hip-width apart.
2. Bend forward at the waist and place your hands on the ground in front of you.
3. Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.
4. Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.
5. Once your hands reach your feet, stand back up to the starting position.
6. Repeat for the desired number of repetitions.', '1471') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3698', 'کرم خاکی (نسخه ۲)', 'Inchworm v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، همسترینگ (پشت ران)', '۱. بایستید و پاها را به اندازه عرض لگن باز کنید.
۲. از کمر به جلو خم شوید و دست‌ها را جلوی خود روی زمین بگذارید.
۳. با دست‌ها به جلو راه بروید تا در وضعیت پلانک با دست صاف و بدن در یک خط صاف قرار بگیرید.
۴. با پاهای صاف، پاها را به سمت دست‌ها ببرید و لگن را به سمت سقف بالا بیاورید.
۵. دوباره با دست‌ها به جلو بروید و حرکت را به تعداد تکرار دلخواه تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3698.gif', 'abs', 'deltoids,hamstring', '1. Start in a standing position with your feet hip-width apart.
2. Bend forward at the waist and place your hands on the ground in front of you.
3. Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.
4. Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.
5. Continue walking your hands forward, repeating the movement for the desired number of repetitions.', '3698') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0490', 'شنا سوئدی شیب‌دار دست جمع', 'Incline close-grip push-up', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. دست‌ها را کمی بازتر از عرض شانه روی یک سطح بلند مانند نیمکت یا پله بگذارید.
۲. پاها را پشت سر دراز کنید و روی پنجه پاها قرار بگیرید تا بدن از سر تا پاشنه یک خط صاف بسازد.
۳. با خم کردن آرنج‌ها سینه را به سمت سطح بلند پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0490.gif', 'triceps', 'chest,deltoids', '1. Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.
2. Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.
3. Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.
4. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '0490') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0491', 'بالا آوردن پا و لگن روی نیمکت شیب‌دار (پای صاف)', 'Incline leg hip raise (leg straight)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. روی نیمکت شیب‌دار دراز بکشید، کمر صاف روی نیمکت و پاها صاف جلوی بدن باشد.
۲. برای حمایت، دست‌ها را روی لبه‌های نیمکت بگذارید.
۳. با درگیر کردن شکم، پاها را از نیمکت بلند کنید و با پاهای صاف تا جای ممکن بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0491.gif', 'abs', 'hip-flexors', '1. Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.
2. Place your hands on the sides of the bench for support.
3. Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0491') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0492', 'شنا سوئدی شیب‌دار با پرش عمقی', 'Incline push up depth jump', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها، میان‌تنه', '۱. یک سطح بلند مانند نیمکت یا پله پیدا کنید و دست‌ها را به اندازه عرض شانه روی لبه آن بگذارید.
۲. پاها را عقب ببرید و بدن را از سر تا پاشنه در یک خط صاف نگه دارید.
۳. با خم کردن آرنج‌ها سینه را به سمت لبه سطح پایین ببرید و بدن را در یک راستا نگه دارید.
۴. با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۵. از لبه سطح پایین بپرید و نرم با زانوهای کمی خم فرود بیایید.
۶. شنا و پرش عمقی را به تعداد تکرار دلخواه تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0492.gif', 'chest', 'triceps,deltoids,abs', '1. Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.
2. Step your feet back, keeping your body in a straight line from head to heels.
3. Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.
4. Push through your palms to extend your arms and return to the starting position.
5. Jump off the edge of the surface, landing softly with your knees slightly bent.
6. Repeat the push-up and depth jump for the desired number of repetitions.', '0492') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0493', 'شنا سوئدی شیب‌دار', 'Incline push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. دست‌ها را کمی بازتر از عرض شانه روی یک سطح بلند مانند نیمکت یا پله بگذارید.
۲. پاها را پشت سر دراز کنید و روی پنجه پاها قرار بگیرید تا بدن از سر تا پاشنه یک خط صاف بسازد.
۳. با خم کردن آرنج‌ها سینه را به سمت سطح بلند پایین ببرید و بدن را در یک خط صاف نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0493.gif', 'chest', 'triceps,deltoids', '1. Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.
2. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.
3. Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.
4. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '0493') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3785', 'شنا سوئدی شیب‌دار (روی جعبه)', 'Incline push-up (on box)', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. دست‌ها را کمی بازتر از عرض شانه روی لبه جعبه یا سطح بلند بگذارید.
۲. پاها را پشت سر دراز کنید و روی پنجه پاها قرار بگیرید تا بدن از سر تا پاشنه یک خط صاف بسازد.
۳. با خم کردن آرنج‌ها سینه را به سمت جعبه پایین ببرید و بدن را در یک خط صاف نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3785.gif', 'chest', 'triceps,deltoids', '1. Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.
2. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.
3. Lower your chest towards the box by bending your elbows, keeping your body in a straight line.
4. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '3785') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0494', 'شنا سوئدی شیب‌دار دست‌برعکس', 'Incline reverse grip push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. دست‌ها را کمی بازتر از عرض شانه روی لبه نیمکت یا سطح بلند بگذارید.
۲. پاها را پشت سر دراز کنید و روی پنجه پاها قرار بگیرید تا بدن از سر تا پاشنه یک خط صاف بسازد.
۳. با خم کردن آرنج‌ها سینه را به سمت نیمکت پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0494.gif', 'chest', 'triceps,deltoids', '1. Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.
2. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.
3. Lower your chest towards the bench by bending your elbows, keeping them close to your sides.
4. Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.
5. Repeat for the desired number of repetitions.', '0494') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3011', 'شنا سوئدی کتف شیب‌دار', 'Incline scapula push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'دندانه‌ای قدامی', 'پشت بازو، شانه‌ها', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. دست‌ها را کمی بازتر از عرض شانه روی نیمکت بگذارید.
۳. پاها را به اندازه عرض لگن روی زمین قرار دهید.
۴. سینه را به سمت نیمکت پایین ببرید و آرنج‌ها را جمع نگه دارید.
۵. هنگام پایین رفتن کتف‌ها را جمع کنید و به هم فشار دهید.
۶. با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3011.gif', 'serratus', 'triceps,deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Place your hands on the bench slightly wider than shoulder-width apart.
3. Position your feet on the ground, hip-width apart.
4. Lower your chest towards the bench, keeping your elbows tucked in.
5. As you lower, retract your shoulder blades, squeezing your scapulae together.
6. Push through your palms to extend your arms and return to the starting position.
7. Repeat for the desired number of repetitions.', '3011') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0495', 'دراز و نشست چرخشی روی نیمکت شیب‌دار', 'Incline twisting sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت دراز بکشید و پاها را زیر پدهای پا محکم کنید.
۳. دست‌ها را پشت سر یا ضربدری روی سینه بگذارید.
۴. شکم را درگیر کنید و بالاتنه را از نیمکت بلند کنید و به جلو خم شوید.
۵. هنگام بالا آمدن، تنه را به یک طرف بچرخانید و آرنج را به سمت زانوی مخالف ببرید.
۶. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۷. حرکت را تکرار کنید و این بار تنه را به طرف دیگر بچرخانید.
۸. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0495.gif', 'abs', 'obliques', '1. Set up an incline bench at a 45-degree angle.
2. Lie down on the bench with your feet secured under the foot pads.
3. Place your hands behind your head or across your chest.
4. Engage your abs and lift your upper body off the bench, curling forward.
5. As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.
6. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
7. Repeat the movement, this time twisting your torso to the other side.
8. Continue alternating sides for the desired number of repetitions.', '0495') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1564', 'کشش خم‌کننده ران و چهارسر (متوسط)', 'Intermediate hip flexor and quad stretch', 'legs', 'پا', 'other', 'سایر', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. صاف بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. برای حمایت یک جسم ثابت را بگیرید.
۳. زانوی راست را خم کنید و پای راست را به سمت باسن بیاورید و طناب را با دست راست بگیرید.
۴. پای راست را آرام به سمت باسن بکشید تا کشش را در جلوی ران راست حس کنید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۶. کشش را رها کنید و برای سمت چپ تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1564.gif', 'quadriceps', 'hamstring,gluteal', '1. Stand upright with your feet shoulder-width apart.
2. Hold onto a stable object for support.
3. Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.
4. Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.
5. Hold the stretch for 20-30 seconds.
6. Release the stretch and repeat on the left side.', '1564') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0496', 'پشت پا معکوس (با تکیه بر نیمکت)', 'Inverse leg curl (bench support)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، ساق پا', '۱. روی نیمکت دمر دراز بکشید، لگن در لبه نیمکت و پاها صاف پشت سر باشد.
۲. برای حمایت نیمکت را بگیرید.
۳. بالاتنه را ثابت نگه دارید، زانوها را خم کنید و پاها را به سمت باسن بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0496.gif', 'hamstring', 'gluteal,calves', '1. Lie face down on a bench with your hips at the edge and your legs extended straight behind you.
2. Hold onto the bench for support.
3. Keeping your upper body still, bend your knees and curl your legs towards your glutes.
4. Pause for a moment at the top, then slowly extend your legs back to the starting position.
5. Repeat for the desired number of repetitions.', '0496') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2400', 'پشت پا معکوس (روی دستگاه بارفیکس سیم‌کش)', 'Inverse leg curl (on pull-up cable machine)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، ساق پا', '۱. سیم‌کش را طوری تنظیم کنید که بندهای مچ پا در پایین‌ترین ارتفاع باشند.
۲. روی نیمکت دمر دراز بکشید، پاها صاف و بندها به پاها بسته شده باشد.
۳. برای ثبات دستگیره‌های نیمکت را بگیرید.
۴. زانوها را خم کنید و پاها را به سمت باسن بیاورید و همسترینگ را منقبض کنید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2400.gif', 'hamstring', 'gluteal,calves', '1. Adjust the cable machine so that the ankle straps are at the lowest setting.
2. Lie face down on the bench with your legs extended and the ankle straps attached to your feet.
3. Hold onto the handles of the bench for stability.
4. Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.
5. Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.
6. Repeat for the desired number of repetitions.', '2400') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0499', 'زیربغل معکوس (اینورتد رو)', 'Inverted row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. یک میله را در ارتفاع کمر قرار دهید یا از تی‌آر‌ایکس استفاده کنید.
۲. رو به میله یا تی‌آر‌ایکس بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله یا دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۴. به عقب متمایل شوید، بدن را صاف و پاشنه‌ها را روی زمین نگه دارید.
۵. سینه را به سمت میله یا دستگیره‌ها بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0499.gif', 'upper-back', 'biceps,forearm', '1. Set up a bar at waist height or use a suspension trainer.
2. Stand facing the bar or suspension trainer, with your feet shoulder-width apart.
3. Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.
4. Lean back, keeping your body straight and your heels on the ground.
5. Pull your chest towards the bar or handles, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower yourself back to the starting position.
7. Repeat for the desired number of repetitions.', '0499') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2300', 'زیربغل معکوس با زانوی خم', 'Inverted row bent knees', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. یک میله را در ارتفاع کمر قرار دهید و زیر آن دراز بکشید.
۲. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۳. بدن را طوری قرار دهید که پاشنه‌ها روی زمین و بدن صاف باشد.
۴. با فشردن کتف‌ها به هم، سینه را به سمت میله بالا بکشید.
۵. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2300.gif', 'upper-back', 'biceps,forearm', '1. Set up a bar at waist height and lie underneath it.
2. Grab the bar with an overhand grip, slightly wider than shoulder-width apart.
3. Position your body so that your heels are on the ground and your body is straight.
4. Pull your chest up towards the bar by squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '2300') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2298', 'زیربغل معکوس روی نیمکت', 'Inverted row on bench', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. نیمکتی را در ارتفاعی قرار دهید که بدن بتواند آزادانه زیر آن آویزان شود.
۲. به پشت روی زمین دراز بکشید و سر رو به نیمکت باشد.
۳. دست‌ها را بالا ببرید و نیمکت را از رو و کمی بازتر از عرض شانه بگیرید.
۴. بدن را طوری قرار دهید که پاشنه‌ها روی زمین و دست‌ها کاملاً صاف باشد.
۵. میان‌تنه را درگیر کنید و با فشردن کتف‌ها به هم سینه را به سمت نیمکت بالا بکشید.
۶. لحظه‌ای در اوج حرکت مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2298.gif', 'upper-back', 'biceps,forearm', '1. Set up a bench at a height that allows your body to hang freely underneath it.
2. Lie face up on the ground with your head towards the bench.
3. Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.
4. Position your body so that your heels are on the ground and your arms are fully extended.
5. Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.
6. Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.
7. Repeat for the desired number of repetitions.', '2298') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0497', 'زیربغل معکوس (نسخه ۲)', 'Inverted row v. 2', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. یک میله را در ارتفاع کمر روی دستگاه اسمیت قرار دهید یا از تی‌آر‌ایکس استفاده کنید.
۲. رو به میله یا تی‌آر‌ایکس بایستید و آن را از رو و به اندازه عرض شانه بگیرید.
۳. پاها را جلو ببرید و به عقب متمایل شوید تا بدن کمی زاویه پیدا کند.
۴. بدن را صاف نگه دارید و سینه را به سمت میله یا دستگیره‌ها بالا بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در بالا مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0497.gif', 'upper-back', 'biceps,forearm', '1. Set up a bar at waist height on a Smith machine or use a suspension trainer.
2. Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.
3. Walk your feet forward, leaning back until your body is at a slight angle.
4. Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '0497') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0498', 'زیربغل معکوس با تسمه', 'Inverted row with straps', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، ساعد', '۱. تی‌آر‌ایکس یا تسمه‌ها را در ارتفاع سینه تنظیم کنید.
۲. رو به نقطه اتصال بایستید و دستگیره‌ها را از رو بگیرید.
۳. پاها را جلو ببرید و به عقب متمایل شوید تا بدن زاویه پیدا کند.
۴. بدن را صاف نگه دارید و میان‌تنه را درگیر کنید.
۵. سینه را به سمت دستگیره‌ها بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0498.gif', 'upper-back', 'biceps,forearm', '1. Set up a suspension trainer or straps at chest height.
2. Stand facing the anchor point and grab the handles with an overhand grip.
3. Walk your feet forward, leaning back until your body is at an angle.
4. Keep your body straight and engage your core.
5. Pull your chest towards the handles, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower yourself back to the starting position.
7. Repeat for the desired number of repetitions.', '0498') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1419', 'کشش صلیب آهنی', 'Iron cross stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. به پشت صاف دراز بکشید و دست‌ها را به طرفین باز کنید.
۲. پاها را صاف به سمت سقف بالا ببرید.
۳. پاها را آرام به یک طرف پایین ببرید تا پاها به زمین برسند.
۴. کشش را چند ثانیه نگه دارید، سپس پاها را به وضعیت شروع برگردانید.
۵. کشش را برای طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1419.gif', 'gluteal', 'hamstring,quadriceps', '1. Lie flat on your back with your arms extended out to the sides.
2. Raise your legs up towards the ceiling, keeping them straight.
3. Slowly lower your legs to one side, aiming to touch the floor with your feet.
4. Hold the stretch for a few seconds, then return your legs to the starting position.
5. Repeat the stretch on the other side.
6. Continue alternating sides for the desired number of repetitions.', '1419') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1297', 'فشار ایزومتریک سینه', 'Isometric chest squeeze', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دست‌ها را صاف جلوی بدن و موازی زمین با کف دست‌های رو به هم دراز کنید.
۳. با دست‌های صاف، عضلات سینه را تا جای ممکن به هم فشار دهید.
۴. این وضعیت را چند ثانیه نگه دارید و روی انقباض عضلات سینه تمرکز کنید.
۵. فشار را رها کنید و عضلات سینه را شل کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1297.gif', 'chest', 'triceps,deltoids', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.
3. Squeeze your chest muscles together as hard as you can, while keeping your arms straight.
4. Hold this position for a few seconds, focusing on contracting your chest muscles.
5. Release the squeeze and relax your chest muscles.
6. Repeat for the desired number of repetitions.', '1297') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0500', 'برف‌پاک‌کن ایزومتریک', 'Isometric wipers', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'شانه‌ها، پشت بازو، میان‌تنه', '۱. به پشت صاف روی تشک یا نیمکت دراز بکشید.
۲. دست‌ها را صاف به طرفین و عمود بر بدن باز کنید.
۳. میان‌تنه را درگیر کنید و هر دو پا را جفت و صاف از زمین بلند کنید.
۴. پاها را آرام به یک طرف پایین ببرید و با حفظ کنترل سعی کنید پاها زمین را لمس کنند.
۵. لحظه‌ای مکث کنید، سپس با کمک میان‌تنه پاها را به وضعیت شروع بالا بیاورید.
۶. حرکت را تکرار کنید و این بار پاها را به طرف مخالف پایین ببرید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0500.gif', 'chest', 'deltoids,triceps,abs', '1. Start by lying flat on your back on a mat or bench.
2. Extend your arms straight out to the sides, perpendicular to your body.
3. Engage your core and lift both legs off the ground, keeping them together and straight.
4. Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.
5. Pause for a moment, then use your core to lift your legs back to the starting position.
6. Repeat the movement, this time lowering your legs to the opposite side.
7. Continue alternating sides for the desired number of repetitions.', '0500') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0507', 'دراز و نشست جک‌نایف', 'Jackknife sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها بالای سر باشد.
۲. میان‌تنه را درگیر کنید و همزمان پاها و بالاتنه را بلند کنید و دست‌ها را به سمت پنجه پاها ببرید.
۳. لحظه‌ای در بالا مکث کنید، سپس پاها و بالاتنه را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0507.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your legs extended and your arms overhead.
2. Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.
3. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.
4. Repeat for the desired number of repetitions.', '0507') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0508', 'دراز و نشست جاندا', 'Janda sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0508.gif', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0508') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0514', 'اسکوات پرشی', 'Jump squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. با باز کردن لگن، زانوها و مچ پاها به صورت انفجاری از زمین بپرید.
۴. در هوا برای حفظ تعادل دست‌ها را سریع به جلو بیاورید.
۵. نرم روی پنجه پاها فرود بیایید و بلافاصله تکرار بعدی را انجام دهید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0514.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. Jump explosively off the ground, extending your hips, knees, and ankles.
4. While in mid-air, quickly bring your arms forward for balance.
5. Land softly on the balls of your feet and immediately go into the next repetition.
6. Repeat for the desired number of repetitions.', '0514') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0513', 'اسکوات پرشی (نسخه ۲)', 'Jump squat v. 2', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. به صورت انفجاری بپرید و لگن و زانوها را کاملاً باز کنید.
۴. نرم روی پنجه پاها فرود بیایید و بلافاصله به حالت اسکوات برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0513.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. Jump explosively, extending your hips and knees fully.
4. Land softly on the balls of your feet and immediately lower your body back into a squat position.
5. Repeat for the desired number of repetitions.', '0513') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0517', 'آسیاب بادی پیشرفته کتل‌بل', 'Kettlebell advanced windmill', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها، شانه‌ها', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. کتل‌بل را در دست راست بگیرید، دست را بالای سر صاف کنید و کف دست رو به جلو باشد.
۳. پای چپ را کمی به راست بچرخانید و وزن را روی پای چپ منتقل کنید.
۴. زانوی چپ را خم کنید و از لگن خم شوید و تنه را به سمت چپ پایین ببرید.
۵. دست راست را بالای سر صاف و نگاه را روی کتل‌بل نگه دارید.
۶. هنگام پایین بردن تنه، اجازه دهید پای راست صاف شود و کف پای راست کمی بچرخد.
۷. تنه را تا جایی پایین ببرید که کشش را در همسترینگ چپ حس کنید و دست راست رو به زمین باشد.
۸. لحظه‌ای مکث کنید، سپس میان‌تنه را درگیر کنید و با فشار پاشنه چپ به وضعیت شروع برگردید.
۹. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0517.gif', 'abs', 'obliques,deltoids', '1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.
2. Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.
3. Rotate your left foot slightly to the right, and shift your weight onto your left leg.
4. Bend your left knee and hinge at the hip, lowering your torso towards the left side.
5. Keep your right arm extended overhead and your eyes on the kettlebell.
6. As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.
7. Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.
8. Pause for a moment, then engage your core and push through your left heel to return to the starting position.
9. Repeat for the desired number of repetitions, then switch sides.', '0517') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0518', 'هنگ کلین یک در میان کتل‌بل', 'Kettlebell alternating hang clean', 'arms', 'بازو', 'other', 'سایر', 'ساعد', 'شانه‌ها، کول (ذوزنقه)، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل را از رو بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۳. اجازه دهید کتل‌بل‌ها با دست‌های کاملاً صاف جلوی بدن آویزان باشند.
۴. در یک حرکت روان، لگن را انفجاری باز کنید، شانه‌ها را بالا بیندازید و کتل‌بل‌ها را به سمت شانه‌ها بالا بکشید.
۵. وقتی کتل‌بل‌ها به ارتفاع شانه رسیدند، مچ‌ها را بچرخانید و آن‌ها را در حالت رک بگیرید؛ کف دست‌ها رو به داخل و کتل‌بل‌ها روی بیرون ساعدها.
۶. کتل‌بل‌ها را به وضعیت شروع پایین بیاورید و حرکت را با دست مقابل تکرار کنید.
۷. به تعداد تکرار دلخواه، دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0518.gif', 'forearm', 'deltoids,trapezius,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.
3. Allow the kettlebells to hang in front of your body with your arms fully extended.
4. In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.
5. As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.
6. Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.
7. Continue alternating arms for the desired number of repetitions.', '0518') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0520', 'پرس یک در میان کتل‌بل', 'Kettlebell alternating press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل در ارتفاع شانه نگه دارید.
۲. یک کتل‌بل را بالای سر پرس کنید و دست را کاملاً صاف کنید.
۳. کتل‌بل را تا ارتفاع شانه پایین بیاورید.
۴. با دست دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0520.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.
2. Press one kettlebell overhead, fully extending your arm.
3. Lower the kettlebell back to shoulder height.
4. Repeat with the other arm.
5. Continue alternating arms for the desired number of repetitions.', '0520') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0519', 'پرس یک در میان روی زمین کتل‌بل', 'Kettlebell alternating press on floor', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'شانه‌ها، پشت بازو', '۱. به پشت روی زمین دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. در هر دست یک کتل‌بل بگیرید، کف دست‌ها رو به پاها و دست‌ها صاف به سمت سقف باشد.
۳. یک کتل‌بل را به سمت شانه پایین بیاورید و کتل‌بل دیگر را صاف بالا نگه دارید.
۴. کتل‌بل پایین را به وضعیت شروع پرس کنید و همزمان کتل‌بل دیگر را به سمت شانه پایین بیاورید.
۵. به تعداد تکرار دلخواه پرس را با هر کتل‌بل یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0519.gif', 'chest', 'deltoids,triceps', '1. Start by lying on your back on the floor with your knees bent and feet flat on the ground.
2. Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.
3. Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.
4. Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.
5. Continue alternating the press motion with each kettlebell for the desired number of repetitions.', '0519') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0521', 'زیربغل رنگید یک در میان کتل‌بل', 'Kettlebell alternating renegade row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'میان‌تنه، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها کتل‌بل‌ها را گرفته و پاها به اندازه عرض لگن باز باشد.
۲. میان‌تنه را درگیر کنید و بدن را از سر تا پاشنه در یک خط صاف نگه دارید.
۳. یک کتل‌بل را به سمت سینه بالا بکشید و آرنج را نزدیک بدن نگه دارید.
۴. کتل‌بل را به وضعیت شروع پایین بیاورید و با دست دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0521.gif', 'upper-back', 'abs,deltoids', '1. Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.
2. Engage your core and keep your body in a straight line from head to heels.
3. Pull one kettlebell up towards your chest, keeping your elbow close to your body.
4. Lower the kettlebell back down to the starting position and repeat with the other arm.
5. Continue alternating arms for the desired number of repetitions.', '0521') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0522', 'زیربغل یک در میان کتل‌بل', 'Kettlebell alternating row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز و زانوها کمی خم باشد و در هر دست یک کتل‌بل با کف دست رو به بدن بگیرید.
۲. از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. یک کتل‌بل را به سمت سینه بالا بکشید، آرنج را نزدیک بدن نگه دارید و کتف‌ها را به هم فشار دهید.
۴. کتل‌بل را به وضعیت شروع پایین بیاورید و با دست دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0522.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.
2. Bend forward at the hips, keeping your back straight and your core engaged.
3. Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.
4. Lower the kettlebell back down to the starting position and repeat with the other arm.
5. Continue alternating arms for the desired number of repetitions.', '0522') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0523', 'پرس آرنولد کتل‌بل', 'Kettlebell arnold press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل در ارتفاع شانه با کف دست رو به خود نگه دارید.
۲. میان‌تنه را درگیر کنید و کتل‌بل‌ها را بالای سر پرس کنید و همزمان با صاف کردن دست‌ها کف دست‌ها را رو به جلو بچرخانید.
۳. در اوج حرکت مکث کنید، سپس کتل‌بل‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0523.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.
2. Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.
3. Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.
4. Repeat for the desired number of repetitions.', '0523') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0524', 'بنت پرس کتل‌بل', 'Kettlebell bent press', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'شانه‌ها، پشت بازو، پهلوها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل در دست راست بگیرید.
۲. زانوها را کمی خم کنید و کتل‌بل را با دست راست بالای سر پرس کنید و آرنج را قفل نگه دارید.
۳. تنه را به چپ بچرخانید و وزن را روی پای چپ منتقل کنید.
۴. زانوی چپ را خم کنید و تنه را به سمت زمین پایین ببرید و دست راست را بالای سر صاف نگه دارید.
۵. هنگام پایین رفتن، نگاه را روی کتل‌بل و سینه را بالا نگه دارید.
۶. وقتی دست چپ به زمین رسید، با فشار پای چپ پا را صاف کنید و لگن را به جلو برانید.
۷. همزمان با راندن لگن به جلو، با کمک میان‌تنه و دست راست کتل‌بل را به وضعیت شروع بالا ببرید.
۸. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0524.gif', 'abs', 'deltoids,triceps,obliques', '1. Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.
2. Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.
3. Rotate your torso to the left, shifting your weight onto your left foot.
4. Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.
5. As you lower, keep your eyes on the kettlebell and your chest lifted.
6. Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.
7. As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.
8. Repeat for the desired number of repetitions, then switch sides.', '0524') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0525', 'کلین وارونه از حالت آویزان کتل‌بل', 'Kettlebell bottoms up clean from the hang position', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل را از رو در یک دست بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۳. اجازه دهید کتل‌بل با دست کاملاً صاف بین پاها آویزان باشد.
۴. در یک حرکت روان، لگن و زانوها را انفجاری باز کنید و کتل‌بل را به سمت شانه بالا بکشید.
۵. وقتی کتل‌بل به ارتفاع شانه رسید، مچ را بچرخانید تا ته کتل‌بل رو به بالا باشد.
۶. کتل‌بل را در ارتفاع شانه با آرنج خم و کف دست رو به بالا بگیرید.
۷. با معکوس کردن حرکت کتل‌بل را به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0525.gif', 'biceps', 'forearm,deltoids', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.
3. Allow the kettlebell to hang down between your legs, with your arm fully extended.
4. In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.
5. As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.
6. Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.
7. Lower the kettlebell back down to the starting position by reversing the movement.
8. Repeat for the desired number of repetitions, then switch sides.', '0525') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0526', 'هنگ کلین دوتایی یک در میان کتل‌بل', 'Kettlebell double alternating hang clean', 'arms', 'بازو', 'other', 'سایر', 'جلو بازو', 'ساعد، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل را از رو بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۳. اجازه دهید کتل‌بل‌ها صاف جلوی بدن آویزان باشند.
۴. در یک حرکت روان، لگن و زانوها را انفجاری باز کنید و شانه‌ها را بالا بیندازید.
۵. همزمان با بالا آمدن کتل‌بل‌ها، آن‌ها را به سمت شانه‌ها بکشید و آرنج‌ها را بالا و رو به طرفین نگه دارید.
۶. کتل‌بل‌ها را در ارتفاع شانه با کف دست رو به داخل و آرنج‌های رو به جلو بگیرید.
۷. کتل‌بل‌ها را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0526.gif', 'biceps', 'forearm,deltoids', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.
3. Allow the kettlebells to hang straight down in front of your body.
4. In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.
5. As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.
6. Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.
7. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.', '0526') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0527', 'جرک دوتایی کتل‌بل', 'Kettlebell double jerk', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل در ارتفاع شانه نگه دارید.
۲. زانوها را کمی خم کنید و میان‌تنه را درگیر کنید.
۳. کتل‌بل‌ها را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۴. زانوها را خم کنید و سریع به یک اسکوات نیمه بروید.
۵. لگن و زانوها را انفجاری باز کنید و کتل‌بل‌ها را بالای سر برانید.
۶. دست‌ها را قفل کنید و کتل‌بل‌ها را بالای سر با زانوهای کمی خم بگیرید.
۷. صاف بایستید و به وضعیت شروع برگردید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0527.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.
2. Bend your knees slightly and engage your core.
3. Press the kettlebells overhead, fully extending your arms.
4. Bend your knees and quickly drop into a partial squat.
5. Explosively extend your hips and knees, driving the kettlebells overhead.
6. Lock out your arms and catch the kettlebells overhead with your knees slightly bent.
7. Stand up straight and return to the starting position.
8. Repeat for the desired number of repetitions.', '0527') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0528', 'پوش پرس دوتایی کتل‌بل', 'Kettlebell double push press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل در ارتفاع شانه نگه دارید.
۲. زانوها را کمی خم کنید و میان‌تنه را درگیر کنید.
۳. حرکت را با باز کردن انفجاری لگن، زانوها و مچ پاها شروع کنید و کتل‌بل‌ها را بالای سر برانید.
۴. وقتی کتل‌بل‌ها به بالا رسیدند، آن‌ها را کاملاً بالای سر پرس کنید و دست‌ها را قفل کنید.
۵. با خم کردن آرنج‌ها کتل‌بل‌ها را تا ارتفاع شانه به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0528.gif', 'deltoids', 'triceps,abs', '1. Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.
2. Bend your knees slightly and engage your core.
3. Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.
4. As the kettlebells reach the top, press them fully overhead, locking out your arms.
5. Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.
6. Repeat for the desired number of repetitions.', '0528') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0529', 'اسنچ دوتایی کتل‌بل', 'Kettlebell double snatch', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'کول (ذوزنقه)، ساعد، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل را با دست صاف جلوی ران‌ها نگه دارید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۳. در یک حرکت انفجاری، لگن، زانوها و مچ پاها را باز کنید و همزمان کتل‌بل‌ها را به سمت شانه‌ها بکشید.
۴. وقتی کتل‌بل‌ها به سطح شانه رسیدند، مچ‌ها را بچرخانید و آن‌ها را بالای سر ضربه بزنید و دست‌ها را کاملاً صاف کنید.
۵. کتل‌بل‌ها را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0529.gif', 'deltoids', 'trapezius,forearm,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.
2. Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.
3. In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.
4. As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.
5. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.', '0529') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0530', 'آسیاب بادی دوتایی کتل‌بل', 'Kettlebell double windmill', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'شانه‌ها، همسترینگ (پشت ران)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل در دست راست بگیرید.
۲. دست راست را بالای سر صاف کنید و نگاه را روی کتل‌بل نگه دارید.
۳. پای چپ را ۴۵ درجه به چپ و پای راست را ۹۰ درجه به راست بچرخانید.
۴. از کمر به چپ خم شوید و دست راست را بالای سر صاف نگه دارید.
۵. کتل‌بل را به سمت زمین پایین ببرید و به سمت پای چپ بروید.
۶. لحظه‌ای مکث کنید، سپس میان‌تنه را درگیر کنید و با فشار پای راست به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0530.gif', 'abs', 'deltoids,hamstring', '1. Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.
2. Extend your right arm overhead, keeping your eyes on the kettlebell.
3. Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.
4. Bend at the waist to the left, keeping your right arm extended overhead.
5. Lower the kettlebell towards the ground, reaching towards your left foot.
6. Pause for a moment, then engage your core and push through your right foot to return to the starting position.
7. Repeat for the desired number of repetitions, then switch sides.', '0530') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0531', 'پرس تک‌دست با دامنه بیشتر روی زمین کتل‌بل', 'Kettlebell extended range one arm press on floor', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'پشت بازو، شانه‌ها', '۱. به پشت روی زمین دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. یک کتل‌بل را در یک دست با کف دست رو به پاها بگیرید.
۳. دست را صاف به سمت سقف ببرید و آرنج را قفل و مچ را صاف نگه دارید.
۴. کتل‌بل را آرام و با کنترل به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0531.gif', 'chest', 'triceps,deltoids', '1. Start by lying on your back on the floor with your knees bent and feet flat on the ground.
2. Hold a kettlebell in one hand, with your palm facing towards your feet.
3. Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.
4. Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '0531') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0532', 'عدد ۸ کتل‌بل', 'Kettlebell figure 8', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'شانه‌ها، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل در یک دست بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. کتل‌بل را از بین پاها رد کنید و وقتی به پشت پاها رسید آن را به دست دیگر بدهید.
۴. وقتی کتل‌بل به جلو آمد، آن را از بین پاها به دست دیگر بدهید.
۵. رد کردن کتل‌بل از بین پاها را به شکل عدد ۸ ادامه دهید.
۶. در طول تمرین سرعت ثابتی داشته باشید و میان‌تنه را درگیر نگه دارید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0532.gif', 'abs', 'deltoids,forearm', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.
4. As the kettlebell comes forward, pass it to the other hand between your legs.
5. Continue passing the kettlebell between your legs in a figure 8 motion.
6. Maintain a steady pace and engage your core throughout the exercise.
7. Repeat for the desired number of repetitions.', '0532') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0533', 'اسکوات از جلو کتل‌بل', 'Kettlebell front squat', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. کتل‌بل را با دو دست جلوی سینه و نزدیک بدن نگه دارید.
۳. میان‌تنه را درگیر و سینه را بالا نگه دارید و لگن را مانند نشستن روی صندلی به پایین و عقب ببرید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. با فشار پاشنه‌ها بایستید و در بالا باسن را منقبض کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0533.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, toes slightly turned out.
2. Hold the kettlebell with both hands in front of your chest, close to your body.
3. Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.
4. Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
5. Drive through your heels to stand back up, squeezing your glutes at the top.
6. Repeat for the desired number of repetitions.', '0533') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0534', 'اسکوات گابلت کتل‌بل', 'Kettlebell goblet squat', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کتل‌بل را با دو دست نزدیک سینه نگه دارید.
۲. سینه را بالا و میان‌تنه را درگیر نگه دارید و با خم کردن زانوها و لگن به حالت اسکوات پایین بروید.
۳. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0534.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.
2. Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.
3. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
4. Pause for a moment at the bottom, then push through your heels to return to the starting position.
5. Repeat for the desired number of repetitions.', '0534') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0535', 'هنگ کلین کتل‌بل', 'Kettlebell hang clean', 'legs', 'پا', 'other', 'سایر', 'همسترینگ (پشت ران)', 'سرینی (باسن)، چهارسر ران، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کتل‌بل را جلوی ران‌ها نگه دارید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. کتل‌بل را به سمت زمین پایین ببرید و اجازه دهید بین پاها تاب بخورد.
۴. سریع لگن و زانوها را باز کنید و با شتاب ایجادشده کتل‌بل را تا ارتفاع شانه تاب دهید.
۵. وقتی کتل‌بل به ارتفاع شانه رسید، مچ را بچرخانید و آن را در حالت رک بگیرید؛ آرنج جمع و کتل‌بل روی ساعد.
۶. کتل‌بل را به وضعیت شروع بین پاها برگردانید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0535.gif', 'hamstring', 'gluteal,quadriceps,calves', '1. Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Lower the kettlebell towards the ground, allowing it to swing between your legs.
4. Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.
5. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.
6. Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions.', '0535') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0536', 'لانج با رد کردن کتل‌بل', 'Kettlebell lunge pass through', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کتل‌بل را با دو دست جلوی سینه نگه دارید.
۲. با پای راست یک گام به جلو بردارید و به حالت لانج پایین بروید.
۳. هنگام لانج به جلو، کتل‌بل را از زیر ران راست رد کنید و به دست چپ بدهید.
۴. با فشار پای راست به وضعیت شروع برگردید و همزمان کتل‌بل را دوباره به دست راست بدهید.
۵. لانج را برای طرف مقابل تکرار کنید و کتل‌بل را از زیر ران چپ رد کنید.
۶. به تعداد تکرار دلخواه لانج‌ها و رد کردن کتل‌بل بین دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0536.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.
2. Take a step forward with your right foot, lowering your body into a lunge position.
3. As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.
4. Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.
5. Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.
6. Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions.', '0536') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0537', 'کلین و جرک تک‌دست کتل‌بل', 'Kettlebell one arm clean and jerk', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل را از رو در یک دست بگیرید.
۲. زانوها را کمی خم کنید و از لگن خم شوید و کتل‌بل را بین پاها پایین ببرید.
۳. لگن، زانوها و مچ پاها را انفجاری باز کنید و با شتاب ایجادشده کتل‌بل را تا ارتفاع شانه تاب دهید.
۴. وقتی کتل‌بل به ارتفاع شانه رسید، مچ را بچرخانید و دست را مستقیم بالا ضربه بزنید و دست را بالای سر قفل کنید.
۵. کتل‌بل را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0537.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.
2. Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.
3. Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.
4. As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.
5. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', '0537') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1298', 'پرس زمین تک‌دست کتل‌بل', 'Kettlebell one arm floor press', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'پشت بازو، شانه‌ها', '۱. به پشت صاف روی زمین دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. کتل‌بل را در یک دست با کف دست رو به پاها بگیرید و دست را صاف به سمت سقف ببرید.
۳. با خم کردن آرنج کتل‌بل را آرام به سمت سینه پایین بیاورید و بازو را نزدیک بدن نگه دارید.
۴. وقتی کتل‌بل کمی بالاتر از سینه قرار گرفت لحظه‌ای مکث کنید، سپس با صاف کردن آرنج آن را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1298.gif', 'chest', 'triceps,deltoids', '1. Lie flat on your back on the floor with your knees bent and feet flat on the ground.
2. Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.
3. Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.
4. Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '1298') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0538', 'جرک تک‌دست کتل‌بل', 'Kettlebell one arm jerk', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل در یک دست در ارتفاع شانه نگه دارید.
۲. زانوها را کمی خم کنید و میان‌تنه را درگیر کنید.
۳. کتل‌بل را در یک خط مستقیم بالای سر پرس کنید و دست را کاملاً صاف کنید.
۴. همزمان با پرس کتل‌بل، زانوها را کمی خم کرده و سریع صاف کنید تا شتاب ایجاد شود.
۵. وقتی کتل‌بل به بالاترین نقطه رسید، سریع با خم کردن زانوها و لگن زیر آن بروید.
۶. کتل‌بل را با زانوها و لگن کمی خم و دست کاملاً صاف بالای سر بگیرید.
۷. صاف بایستید، زانوها و لگن را کاملاً باز کنید و کتل‌بل را بالای سر ثابت نگه دارید.
۸. با خم کردن زانوها و لگن کتل‌بل را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0538.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.
2. Bend your knees slightly and engage your core.
3. Press the kettlebell overhead in a straight line, fully extending your arm.
4. As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.
5. As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.
6. Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.
7. Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.
8. Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions.', '0538') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0539', 'پرس نظامی تک‌دست به پهلو کتل‌بل', 'Kettlebell one arm military press to the side', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل در یک دست در ارتفاع شانه نگه دارید.
۲. میان‌تنه را درگیر و کمر را صاف نگه دارید.
۳. کتل‌بل را بالای سر پرس کنید و دست را کاملاً صاف کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس کتل‌بل را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0539.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.
2. Engage your core and keep your back straight.
3. Press the kettlebell overhead, extending your arm fully.
4. Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '0539') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0540', 'پوش پرس تک‌دست کتل‌بل', 'Kettlebell one arm push press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل در یک دست در سطح شانه نگه دارید.
۲. زانوها را کمی خم کنید و میان‌تنه را درگیر کنید.
۳. با صاف کردن دست و باز کردن کامل پاها، کتل‌بل را بالای سر پرس کنید.
۴. با خم کردن زانوها و آوردن کتل‌بل به شانه، به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0540.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.
2. Bend your knees slightly and engage your core.
3. Press the kettlebell overhead by extending your arm and fully extending your legs.
4. Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.
5. Repeat for the desired number of repetitions, then switch sides.', '0540') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0541', 'زیربغل تک‌دست کتل‌بل', 'Kettlebell one arm row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل را از رو در یک دست بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. کتل‌بل را به سمت سینه بالا بکشید، آرنج را نزدیک بدن نگه دارید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در بالا مکث کنید، سپس کتل‌بل را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کرده و با دست دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0541.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.
3. Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.
4. Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.', '0541') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0542', 'اسنچ تک‌دست کتل‌بل', 'Kettlebell one arm snatch', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'کول (ذوزنقه)، ساعد، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل را در یک دست بین پاها نگه دارید.
۲. زانوها را کمی خم کنید و از لگن خم شوید و کتل‌بل را به سمت زمین پایین ببرید.
۳. لگن و زانوها را انفجاری باز کنید و با شتاب ایجادشده کتل‌بل را به سمت شانه تاب دهید.
۴. وقتی کتل‌بل به ارتفاع شانه رسید، دست را بچرخانید و مستقیم بالای سر ضربه بزنید و دست را کاملاً صاف کنید.
۵. کتل‌بل را بین پاها پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0542.gif', 'deltoids', 'trapezius,forearm,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.
2. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.
3. Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.
4. As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.
5. Lower the kettlebell back down between your legs and repeat for the desired number of repetitions.', '0542') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0543', 'دزد دریایی کتل‌بل', 'Kettlebell pirate supper legs', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک کتل‌بل در یک دست بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. کتل‌بل را تا ارتفاع شانه بالا بیاورید و آرنج را نزدیک بدن نگه دارید.
۴. دست را کاملاً بالای سر صاف کنید و آرنج را باز کنید.
۵. کتل‌بل را تا ارتفاع شانه پایین بیاورید، سپس به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0543.gif', 'deltoids', 'triceps,forearm', '1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Raise the kettlebell up to shoulder height, keeping your elbow close to your body.
4. Extend your arm fully overhead, straightening your elbow.
5. Lower the kettlebell back down to shoulder height, then return to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '0543') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0544', 'اسکوات پیستول کتل‌بل', 'Kettlebell pistol squat', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کتل‌بل را با دو دست جلوی سینه نگه دارید.
۲. پای چپ را از زمین بلند کنید و به جلو و موازی زمین دراز کنید.
۳. بدن را آرام به حالت اسکوات پایین ببرید، کف پای راست روی زمین و پای چپ کشیده بماند.
۴. لحظه‌ای در پایین اسکوات مکث کنید، سپس با فشار پاشنه راست به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0544.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.
2. Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.
3. Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.
4. Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '0544') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0545', 'شنا سوئدی پلایو کتل‌بل', 'Kettlebell plyo push-up', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'پشت بازو، شانه‌ها، میان‌تنه', '۱. در وضعیت پلانک با دست صاف قرار بگیرید و دست‌ها را به اندازه عرض شانه روی کتل‌بل‌ها بگذارید.
۲. سینه را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک بدن نگه دارید.
۳. با فشار انفجاری دست‌ها، دست‌ها را از کتل‌بل‌ها جدا کنید و کاملاً صاف کنید.
۴. نرم روی کتل‌بل‌ها فرود بیایید و بلافاصله سینه را برای تکرار بعدی پایین ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0545.gif', 'chest', 'triceps,deltoids,abs', '1. Start in a high plank position with your hands on the kettlebells, shoulder-width apart.
2. Lower your chest towards the ground, keeping your elbows close to your body.
3. Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.
4. Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.
5. Repeat for the desired number of repetitions.', '0545') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0546', 'پرس نشسته کتل‌بل', 'Kettlebell seated press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. در هر دست یک کتل‌بل در ارتفاع شانه با کف دست رو به جلو نگه دارید.
۳. کتل‌بل‌ها را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۴. کتل‌بل‌ها را تا ارتفاع شانه پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0546.gif', 'deltoids', 'triceps,abs', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a kettlebell in each hand at shoulder height, palms facing forward.
3. Press the kettlebells overhead, fully extending your arms.
4. Lower the kettlebells back to shoulder height.
5. Repeat for the desired number of repetitions.', '0546') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1438', 'پرس نظامی دو دست نشسته کتل‌بل', 'Kettlebell seated two arm military press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. در هر دست یک کتل‌بل در سطح شانه با کف دست رو به جلو نگه دارید.
۳. با صاف کردن کامل دست‌ها کتل‌بل‌ها را بالای سر پرس کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس کتل‌بل‌ها را آرام تا سطح شانه پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1438.gif', 'deltoids', 'triceps,upper-back', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a kettlebell in each hand at shoulder level with your palms facing forward.
3. Press the kettlebells overhead by extending your arms fully.
4. Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.
5. Repeat for the desired number of repetitions.', '1438') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0547', 'پرس الاکلنگی کتل‌بل', 'Kettlebell seesaw press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل در ارتفاع شانه نگه دارید.
۲. یک کتل‌بل را بالای سر پرس کنید و کتل‌بل دیگر را در ارتفاع شانه نگه دارید.
۳. کتل‌بل بالا را تا ارتفاع شانه پایین بیاورید و همزمان کتل‌بل دیگر را بالای سر پرس کنید.
۴. این حرکت پرس را مانند الاکلنگ یکی در میان ادامه دهید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0547.gif', 'deltoids', 'triceps,abs', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.
2. Press one kettlebell overhead while keeping the other kettlebell at shoulder height.
3. Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.
4. Continue alternating the pressing motion, creating a seesaw-like movement.
5. Repeat for the desired number of repetitions.', '0547') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0548', 'های‌پول سومو کتل‌بل', 'Kettlebell sumo high pull', 'back', 'پشت و زیربغل', 'other', 'سایر', 'کول (ذوزنقه)', 'شانه‌ها، سرینی (باسن)، همسترینگ (پشت ران)', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را به بیرون بچرخانید.
۲. یک کتل‌بل را با دو دست جلوی بدن و با دست‌های صاف رو به پایین نگه دارید.
۳. زانوها را خم کنید و لگن را به حالت اسکوات پایین ببرید و کمر را صاف نگه دارید.
۴. با فشار پاشنه‌ها لگن و زانوها را انفجاری باز کنید و کتل‌بل را به سمت چانه بالا بکشید.
۵. هنگام بالا کشیدن کتل‌بل، آرنج‌ها را بالا و باز نگه دارید و کتف‌ها را به هم فشار دهید.
۶. کتل‌بل را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0548.gif', 'trapezius', 'deltoids,gluteal,hamstring', '1. Stand with your feet wider than shoulder-width apart, toes pointing outwards.
2. Hold a kettlebell with both hands in front of your body, arms extended downwards.
3. Bend your knees and lower your hips into a squat position, keeping your back straight.
4. Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.
5. As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.
6. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', '0548') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0549', 'سوئینگ کتل‌بل', 'Kettlebell swing', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. کتل‌بل را با دو دست و دست‌های صاف جلوی بدن نگه دارید.
۳. زانوها را کمی خم کنید و از لگن خم شوید و باسن را به عقب ببرید.
۴. کتل‌بل را با دست‌های صاف و کمر صاف بین پاها به عقب تاب دهید.
۵. لگن را به جلو برانید و با شتاب ایجادشده از لگن کتل‌بل را تا ارتفاع شانه تاب دهید.
۶. اجازه دهید کتل‌بل دوباره بین پاها تاب بخورد و حرکت را به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0549.gif', 'gluteal', 'hamstring,abs', '1. Stand with your feet shoulder-width apart, toes pointed slightly outward.
2. Hold the kettlebell with both hands in front of your body, arms extended.
3. Bend your knees slightly and hinge at the hips, pushing your butt back.
4. Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.
5. Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.
6. Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions.', '0549') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0550', 'تراستر کتل‌بل', 'Kettlebell thruster', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'چهارسر ران، سرینی (باسن)، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کتل‌بل را با دو دست و کف دست‌های رو به هم جلوی سینه نگه دارید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید و سینه را بالا و کمر را صاف نگه دارید.
۳. در پایین اسکوات، با فشار انفجاری پاشنه‌ها بایستید و همزمان کتل‌بل را بالای سر پرس کنید.
۴. در اوج حرکت دست‌ها را قفل کنید و آرنج‌ها را کاملاً صاف کنید.
۵. با معکوس کردن حرکت، آرنج‌ها را خم کنید و کتل‌بل را به سینه برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0550.gif', 'deltoids', 'quadriceps,gluteal,abs', '1. Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.
2. Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.
3. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.
4. Lock out your arms at the top of the movement, fully extending your elbows.
5. Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.
6. Repeat for the desired number of repetitions.', '0550') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0551', 'ترکیش گت‌آپ کتل‌بل (حالت اسکوات)', 'Kettlebell turkish get up (squat style)', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، میان‌تنه', '۱. به پشت دراز بکشید، پاها صاف و کتل‌بل در دست راست با دست کاملاً صاف بالای شانه باشد.
۲. زانوی راست را خم کنید و کف پای راست را روی زمین بگذارید و پای چپ را صاف نگه دارید.
۳. با فشار پای راست لگن را از زمین بلند کنید و به حالت پل بروید.
۴. پای چپ را زیر بدن بکشید، زانوی چپ را خم کنید و کف پای چپ را روی زمین بگذارید.
۵. تنه را به چپ بچرخانید و برای حمایت دست چپ را روی زمین بگذارید.
۶. با فشار پای راست و دست چپ تنه را از زمین بلند کنید و به حالت زانو زده بروید.
۷. از حالت زانو زده بایستید و کتل‌بل را بالای سر صاف نگه دارید.
۸. حرکت را معکوس کنید تا به وضعیت شروع برگردید.
۹. تمرین را برای طرف دیگر با کتل‌بل در دست چپ تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0551.gif', 'gluteal', 'quadriceps,hamstring,abs', '1. Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.
2. Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.
3. Pressing through your right foot, lift your hips off the ground, coming into a bridge position.
4. Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.
5. Rotate your torso to the left, bringing your left hand to the ground for support.
6. Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.
7. From the kneeling position, stand up, keeping the kettlebell extended overhead.
8. Reverse the movement to return to the starting position.
9. Repeat the exercise on the other side, starting with the kettlebell in your left hand.', '0551') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0552', 'کلین دو دست کتل‌بل', 'Kettlebell two arm clean', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'کول (ذوزنقه)، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کتل‌بل را با دو دست و کف دست رو به خود جلوی ران‌ها نگه دارید.
۲. زانوها را کمی خم کنید و از لگن خم شوید و کتل‌بل را به سمت زمین پایین ببرید.
۳. لگن و زانوها را انفجاری باز کنید و با شتاب ایجادشده کتل‌بل را به سمت شانه‌ها بالا بکشید.
۴. وقتی کتل‌بل به ارتفاع شانه رسید، مچ‌ها را بچرخانید و آن را در حالت رک بگیرید؛ آرنج‌ها جمع و کتل‌بل روی پشت ساعد.
۵. کتل‌بل را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0552.gif', 'deltoids', 'trapezius,forearm', '1. Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.
2. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.
3. Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.
4. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.
5. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', '0552') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0553', 'پرس نظامی دو دست کتل‌بل', 'Kettlebell two arm military press', 'shoulders', 'سرشانه', 'other', 'سایر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک کتل‌بل در سطح شانه با کف دست رو به جلو نگه دارید.
۲. میان‌تنه را درگیر کنید و کتل‌بل‌ها را بالای سر پرس کنید و دست‌ها را کاملاً صاف کنید.
۳. لحظه‌ای در بالا مکث کنید، سپس کتل‌بل‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0553.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.
2. Engage your core and press the kettlebells overhead, fully extending your arms.
3. Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.
4. Repeat for the desired number of repetitions.', '0553') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1345', 'زیربغل دو دست کتل‌بل', 'Kettlebell two arm row', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز و زانوها کمی خم باشد و در هر دست یک کتل‌بل با کف دست رو به بدن بگیرید.
۲. از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. کتل‌بل‌ها را به سمت سینه بالا بکشید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در بالا مکث کنید، سپس کتل‌بل‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1345.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.
2. Bend forward at the hips, keeping your back straight and your core engaged.
3. Pull the kettlebells up towards your chest, squeezing your shoulder blades together.
4. Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.
5. Repeat for the desired number of repetitions.', '1345') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0554', 'آسیاب بادی کتل‌بل', 'Kettlebell windmill', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پهلوها، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و کتل‌بل را با دست راست بالای سر نگه دارید.
۲. پای چپ را حدود ۴۵ درجه به بیرون بچرخانید و پای راست را رو به جلو نگه دارید.
۳. تنه را به سمت چپ خم کنید، دست راست را بالای سر صاف و نگاه را روی کتل‌بل نگه دارید.
۴. تنه را تا جای ممکن پایین ببرید و دست راست را صاف و دست چپ را به طرف باز نگه دارید.
۵. لحظه‌ای مکث کنید، سپس با فشار پای راست و درگیر کردن پهلوها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0554.gif', 'abs', 'obliques,deltoids', '1. Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.
2. Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.
3. Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.
4. Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.
5. Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.
6. Repeat for the desired number of repetitions, then switch sides.', '0554') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0555', 'نشسته با ضربه پا به بیرون', 'Kick out sit', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'چهارسر ران، سرینی (باسن)', '۱. لبه نیمکت یا صندلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. کمی به عقب متمایل شوید و برای حمایت دست‌ها را روی لبه نیمکت یا صندلی بگذارید.
۳. با درگیر کردن همسترینگ، پاها را از زمین بلند کنید و صاف جلوی بدن دراز کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس زانوها را آرام خم کنید و پاها را به سمت بدن برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0555.gif', 'hamstring', 'quadriceps,gluteal', '1. Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Lean back slightly and place your hands on the edge of the bench or chair for support.
3. Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.
4. Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.
5. Repeat for the desired number of repetitions.', '0555') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0558', 'ماسل‌آپ کیپینگ', 'Kipping muscle up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، پشت بازو، شانه‌ها، میان‌تنه', '۱. از میله بارفیکس با دست‌های از رو و کمی بازتر از عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و با یک حرکت تابی شتاب ایجاد کنید.
۳. هنگام تاب خوردن به جلو، با کمک زیربغل و جلو بازو سینه را به سمت میله بکشید.
۴. حرکت رو به بالا را تا رسیدن سینه به میله ادامه دهید، سپس با فشار روی میله و صاف کردن دست‌ها به حالت دیپ بروید.
۵. با خم کردن دست‌ها و کنترل پایین آمدن، به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0558.gif', 'upper-back', 'biceps,triceps,deltoids,abs', '1. Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.
2. Engage your core and use a swinging motion to generate momentum.
3. As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.
4. Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.
5. Lower yourself back down to the starting position by bending your arms and controlling the descent.
6. Repeat for the desired number of repetitions.', '0558') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3640', 'کرانچ با لمس زانو', 'Knee touch crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن شکم، کتف‌ها را از زمین بلند کنید و دست راست را به سمت زانوی چپ ببرید.
۴. به وضعیت شروع برگردید و تکرار کنید، این بار دست چپ را به سمت زانوی راست ببرید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3640.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.
4. Return to the starting position and repeat, this time reaching your left hand towards your right knee.
5. Continue alternating sides for the desired number of repetitions.', '3640') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1420', 'اسکوات پرشی از حالت زانو زده', 'Kneeling jump squat', 'legs', 'پا', 'barbell', 'هالتر', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. روی زمین زانو بزنید، پاها به اندازه عرض لگن باز و پنجه‌ها رو به جلو باشد.
۲. هالتر را روی بالای کمر و روی شانه‌ها قرار دهید.
۳. میان‌تنه و باسن را درگیر کنید و با باز کردن لگن و زانوها انفجاری به هوا بپرید.
۴. هنگام پرش از پنجه پا نیرو بگیرید و مچ پا، زانوها و لگن را کاملاً باز کنید.
۵. نرم روی زمین فرود بیایید و برای جذب ضربه زانوها را خم کنید.
۶. بلافاصله تکرار بعدی را انجام دهید و حرکت اسکوات پرشی را تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1420.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.
2. Hold a barbell across your upper back, resting it on your shoulders.
3. Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.
4. As you jump, push through your toes and fully extend your ankles, knees, and hips.
5. Land softly back on the ground, bending your knees to absorb the impact.
6. Immediately go into the next repetition, repeating the jump squat motion.', '1420') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1346', 'کشش زیربغل زانو زده', 'Kneeling lat stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'شانه‌ها، پشت بازو', '۱. روی زمین زانو بزنید، زانوها به اندازه عرض لگن باز و پنجه‌ها رو به عقب باشد.
۲. دست‌ها را بالای سر ببرید و انگشتان را در هم قفل کنید.
۳. با کمر صاف، آرام به سمت راست خم شوید تا کشش را در زیربغل چپ حس کنید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس به وضعیت شروع برگردید.
۵. کشش را برای سمت چپ تکرار کنید، به چپ خم شوید و کشش را در زیربغل راست حس کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1346.gif', 'upper-back', 'deltoids,triceps', '1. Kneel on the ground with your knees hip-width apart and your toes pointing back.
2. Extend your arms overhead and interlace your fingers.
3. Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.
4. Hold the stretch for 20-30 seconds, then return to the starting position.
5. Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.
6. Continue alternating sides for the desired number of repetitions.', '1346') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3239', 'پلانک زانو زده با لمس شانه', 'Kneeling plank tap shoulder (male)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، پشت بازو', '۱. در حالت زانو زده قرار بگیرید و دست‌ها را به اندازه عرض شانه روی زمین بگذارید.
۲. پاها را پشت سر دراز کنید، روی پنجه‌ها قرار بگیرید و بدن را به حالت پلانک بالا ببرید.
۳. با میان‌تنه درگیر و لگن ثابت، یک دست را از زمین بلند کنید و به شانه مخالف ضربه بزنید.
۴. دست را به زمین برگردانید و با دست دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3239.gif', 'abs', 'deltoids,triceps', '1. Start in a kneeling position with your hands on the ground, shoulder-width apart.
2. Extend your legs behind you, resting on your toes, and lift your body into a plank position.
3. Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.
4. Return the hand to the ground and repeat with the other hand.
5. Continue alternating sides for the desired number of repetitions.', '3239') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3211', 'شنا سوئدی زانو زده', 'Kneeling push-up (male)', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. روی زمین زانو بزنید و دست‌ها را به اندازه عرض شانه با انگشتان رو به جلو بگذارید.
۲. پاها را پشت سر دراز کنید و روی پنجه پاها قرار بگیرید تا بدن از سر تا پاشنه یک خط صاف بسازد.
۳. میان‌تنه را درگیر کنید و با خم کردن آرنج‌ها بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۴. تا جایی پایین بروید که سینه کمی بالاتر از زمین قرار گیرد، سپس با صاف کردن دست‌ها به وضعیت شروع بالا بروید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3211.gif', 'chest', 'triceps,deltoids', '1. Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.
2. Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.
3. Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.
4. Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '3211') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3288', 'دیپ کره‌ای', 'Korean dips', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. بین دو میله موازی قرار بگیرید و با دست‌های صاف وزن بدن را نگه دارید.
۲. با خم کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.
۳. لحظه‌ای مکث کنید، سپس با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3288.gif', 'chest', 'triceps,deltoids', '1. Position yourself between two parallel bars with your arms extended and supporting your body weight.
2. Lower your body by bending your elbows until your upper arms are parallel to the ground.
3. Pause for a moment, then push yourself back up to the starting position by straightening your arms.
4. Repeat for the desired number of repetitions.', '3288') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3418', 'بارفیکس L', 'L-pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. میله بارفیکس را از رو و کمی بازتر از عرض شانه بگیرید.
۲. با دست‌های کاملاً صاف و بدن صاف آویزان شوید.
۳. زیربغل و جلو بازو را درگیر کنید و بدن را به سمت میله بالا بکشید و آرنج‌ها را نزدیک بدن نگه دارید.
۴. تا جایی بالا بروید که چانه بالای میله قرار بگیرد.
۵. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3418.gif', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Hang with your arms fully extended and your body straight.
3. Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '3418') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3419', 'ال‌سیت روی زمین', 'L-sit on floor', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. روی زمین بنشینید و پاها را جلوی بدن دراز کنید.
۲. دست‌ها را کنار لگن روی زمین بگذارید، انگشتان رو به جلو.
۳. میان‌تنه را درگیر کنید و پاها را صاف از زمین بلند کنید.
۴. سعی کنید پاها را موازی زمین بیاورید تا بدن شکل «L» بسازد.
۵. این وضعیت را تا جای ممکن نگه دارید.
۶. پاها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3419.gif', 'abs', 'hip-flexors', '1. Sit on the floor with your legs extended in front of you.
2. Place your hands on the floor beside your hips, fingers pointing forward.
3. Engage your core and lift your legs off the ground, keeping them straight.
4. Try to bring your legs parallel to the floor, forming an ''L'' shape with your body.
5. Hold this position for as long as you can.
6. Slowly lower your legs back down to the starting position.
7. Repeat for the desired number of repetitions.', '3419') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0562', 'لندماین ۱۸۰', 'Landmine 180', 'core', 'شکم و میان‌تنه', 'barbell', 'هالتر', 'شکم', 'پهلوها، چهارسر ران', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را با دو دست جلوی سینه نگه دارید.
۲. زانوها را کمی خم کنید و تنه را به راست بچرخانید و هالتر را به سمت لگن راست پایین ببرید.
۳. در پایین حرکت، سریع جهت را عوض کنید و تنه را به چپ بچرخانید و هالتر را از جلوی بدن به سمت شانه چپ بالا ببرید.
۴. این حرکت چرخشی را به تعداد تکرار دلخواه و یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0562.gif', 'abs', 'obliques,quadriceps', '1. Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.
2. Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.
3. As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.
4. Continue this twisting motion, alternating sides, for the desired number of repetitions.', '0562') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3237', 'نشر جانب لندماین', 'Landmine lateral raise', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'کول (ذوزنقه)، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را از رو بگیرید و روی جلوی شانه‌ها قرار دهید.
۳. با میان‌تنه درگیر و کمر صاف، هالتر را بالا و دور از بدن تا ارتفاع شانه ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3237.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold the barbell with an overhand grip, resting it on the front of your shoulders.
3. Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.
4. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '3237') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3300', 'پلانچ متمایل', 'Lean planche', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، سینه، پشت بازو', '۱. در وضعیت شنا قرار بگیرید، دست‌ها به اندازه عرض شانه و بدن صاف باشد.
۲. میان‌تنه را درگیر کنید و وزن را آرام به جلو منتقل کنید تا شانه‌ها از دست‌ها جلوتر بروند.
۳. هنگام متمایل شدن به جلو، آرنج‌ها را کمی خم و بدن را صاف نگه دارید.
۴. این وضعیت را چند ثانیه نگه دارید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3300.gif', 'abs', 'deltoids,chest,triceps', '1. Start in a push-up position with your hands shoulder-width apart and your body straight.
2. Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.
3. Keep your elbows slightly bent and your body straight as you lean forward.
4. Hold this position for a few seconds, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '3300') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2271', 'هوک چپ بوکس', 'Left hook. boxing', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'سرشانه', 'جلو بازو، پشت بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دست چپ را برای محافظت از صورت بالا و دست راست را کنار چانه نگه دارید.
۳. لگن را بچرخانید و روی پای چپ بچرخید و همزمان دست چپ را با حرکت مشت به جلو بزنید.
۴. تنه را بچرخانید و عضلات میان‌تنه را برای ایجاد قدرت در ضربه درگیر کنید.
۵. دست را سریع به وضعیت شروع برگردانید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2271.gif', 'deltoids', 'biceps,triceps,forearm', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Keep your left hand up to protect your face and your right hand by your chin.
3. Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.
4. Twist your torso and engage your core muscles to generate power in the punch.
5. Snap your arm back to the starting position and repeat for the desired number of repetitions.', '2271') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0570', 'جمع کردن پا روی نیمکت صاف', 'Leg pull in flat bench', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. روی نیمکت صاف بنشینید و پاها را صاف جلوی بدن دراز کنید.
۲. برای حمایت دست‌ها را کنار لگن روی نیمکت بگذارید.
۳. شکم را درگیر کنید و پاها را از زمین بلند کنید و زانوها را به سمت سینه بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0570.gif', 'abs', 'hip-flexors,lower-back', '1. Sit on a flat bench with your legs extended straight out in front of you.
2. Place your hands on the bench beside your hips for support.
3. Engage your abs and lift your legs off the ground, bringing your knees towards your chest.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0570') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1576', 'کشش همسترینگ با پای بالا', 'Leg up hamstring stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)', '۱. به پشت صاف دراز بکشید و پاها را صاف کنید.
۲. یک زانو را خم کنید و به سمت سینه بیاورید و ران یا ساق را بگیرید.
۳. پا را تا جای ممکن صاف کنید و بالا نگه دارید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1576.gif', 'hamstring', 'gluteal', '1. Lie flat on your back with your legs extended.
2. Bend one knee and bring it towards your chest, holding onto your thigh or shin.
3. Straighten your leg as much as possible while keeping it elevated.
4. Hold the stretch for 20-30 seconds.
5. Repeat with the other leg.', '1576') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2287', 'پرس پا یک در میان دستگاه', 'Lever alternate leg press', 'legs', 'پا', 'machine', 'دستگاه', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. صندلی و سکوی پای دستگاه را در وضعیت دلخواه تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پشتی و پاها روی سکو باشد.
۳. برای ثبات دست‌ها را روی دستگیره‌ها یا کناره‌های دستگاه بگذارید.
۴. یک پا را به سکو فشار دهید و پا را تا تقریباً صاف شدن کامل باز کنید.
۵. لحظه‌ای مکث کنید، سپس پا را آرام خم کنید و به وضعیت شروع برگردید.
۶. با پای دیگر تکرار کنید.
۷. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2287.gif', 'quadriceps', 'hamstring,gluteal', '1. Adjust the seat and foot platform of the leverage machine to your desired position.
2. Sit on the machine with your back against the backrest and your feet on the foot platform.
3. Place your hands on the handles or sides of the machine for stability.
4. Push one foot against the foot platform, extending your leg until it is almost fully straight.
5. Pause for a moment, then slowly bend your leg and return to the starting position.
6. Repeat with the other leg.
7. Continue alternating legs for the desired number of repetitions.', '2287') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0571', 'قایقی نشسته دست جمع یک در میان دستگاه', 'Lever alternating narrow grip seated row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. ارتفاع صندلی و جای پا را برای قرارگیری صحیح تنظیم کنید.
۲. روی دستگاه با کمر صاف بنشینید و کف پاها روی جای پا باشد.
۳. دستگیره‌ها را با دست‌های جمع و کف دست‌های رو به هم بگیرید.
۴. در طول تمرین سینه را بالا و شانه‌ها را عقب نگه دارید.
۵. یک دستگیره را به سمت تنه بکشید و دستگیره دیگر را ثابت نگه دارید.
۶. در انتهای حرکت کتف‌ها را به هم فشار دهید.
۷. دستگیره را آرام به وضعیت شروع برگردانید و با طرف دیگر تکرار کنید.
۸. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0571.gif', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and footplate position to ensure proper alignment.
2. Sit on the machine with your back straight and feet flat on the footplate.
3. Grasp the handles with a narrow grip, palms facing each other.
4. Keep your chest up and shoulders back throughout the exercise.
5. Pull one handle towards your torso while keeping the other handle stationary.
6. Squeeze your shoulder blades together at the end of the movement.
7. Slowly return the handle to the starting position and repeat with the other side.
8. Continue alternating sides for the desired number of repetitions.', '0571') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0572', 'بارفیکس دست‌برعکس با کمک دستگاه', 'Lever assisted chin-up', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، ساعد', '۱. دستگاه را روی مقاومت دلخواه تنظیم کنید.
۲. روی سکوی پا بایستید و دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف و بدن صاف آویزان شوید.
۴. عضلات پشت را درگیر کنید و با هدایت سینه، بدن را به سمت دستگیره‌ها بالا بکشید.
۵. تا جایی بالا بروید که چانه بالای دستگیره‌ها قرار بگیرد.
۶. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0572.gif', 'upper-back', 'biceps,forearm', '1. Adjust the leverage machine to your desired resistance level.
2. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Hang with your arms fully extended, keeping your body straight.
4. Engage your back muscles and pull your body up towards the handles, leading with your chest.
5. Continue pulling until your chin is above the handles.
6. Pause for a moment at the top, then slowly lower your body back down to the starting position.
7. Repeat for the desired number of repetitions.', '0572') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0573', 'فیله کمر دستگاه', 'Lever back extension', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. دستگاه را متناسب با اندازه بدن و دامنه حرکتی خود تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد و پاها محکم باشد.
۳. دست‌ها را روی دستگیره‌ها یا میله‌ها بگذارید.
۴. میان‌تنه را درگیر کنید و آرام به جلو خم شوید و اجازه دهید کمر کمی گرد شود.
۵. لحظه‌ای در پایین مکث کنید و کشش را در پایین کمر حس کنید.
۶. با کمک عضلات کمر تنه را آرام به وضعیت شروع بالا بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0573.gif', 'lower-back', 'gluteal,hamstring', '1. Adjust the machine to fit your body size and range of motion.
2. Sit on the machine with your back against the pad and your feet secured.
3. Place your hands on the handles or grip bars.
4. Engage your core and slowly lean forward, allowing your back to round slightly.
5. Pause for a moment at the bottom position, feeling a stretch in your lower back.
6. Using your back muscles, slowly raise your torso back to the starting position.
7. Repeat for the desired number of repetitions.', '0573') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0574', 'زیربغل خم دستگاه', 'Lever bent over row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۴. هالتر را به سمت پایین سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0574.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Bend forward at the hips, keeping your back straight and chest up.
4. Pull the barbell towards your lower chest, squeezing your shoulder blades together.
5. Pause for a moment at the top, then slowly lower the barbell back to the starting position.
6. Repeat for the desired number of repetitions.', '0574') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3200', 'زیربغل خم با دستگیره V دستگاه', 'Lever bent-over row with v-bar', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. ارتفاع صندلی را تنظیم کنید و رو به دستگاه قرار بگیرید.
۲. دستگیره V را از رو بگیرید و کمر را صاف و زانوها را کمی خم نگه دارید.
۳. دستگیره V را به سمت شکم بکشید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در اوج حرکت مکث کنید، سپس وزنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3200.gif', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and position yourself facing the machine.
2. Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.
3. Pull the v-bar towards your abdomen, squeezing your shoulder blades together.
4. Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.
5. Repeat for the desired number of repetitions.', '3200') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0575', 'جلو بازو دستگاه', 'Lever bicep curl', 'arms', 'بازو', 'machine', 'دستگاه', 'جلو بازو', 'ساعد', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پد بنشینید.
۲. دستگیره‌ها را از زیر با کف دست رو به بالا بگیرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. با بازدم دستگیره‌ها را با انقباض جلو بازو بالا بیاورید.
۴. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0575.gif', 'biceps', 'forearm', '1. Adjust the seat height and position yourself on the machine with your back against the pad.
2. Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.
3. Exhale and curl the handles upward, contracting your biceps.
4. Pause for a moment at the top of the movement, squeezing your biceps.
5. Inhale and slowly lower the handles back to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '0575') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2289', 'ساق پا پرسی دستگاه', 'Lever calf press', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)', '۱. صندلی دستگاه را طوری تنظیم کنید که شانه‌ها هم‌تراز با پد اهرم باشند.
۲. پنجه پاها را روی پد اهرم بگذارید و پاشنه‌ها از لبه آزاد باشند.
۳. برای ثبات دستگیره‌ها یا تکیه‌گاه‌های کناری را بگیرید.
۴. با باز کردن مچ پاها و انقباض ساق، پد اهرم را به پایین فشار دهید.
۵. لحظه‌ای در پایین حرکت مکث کنید.
۶. اجازه دهید پاشنه‌ها بالا بیایند و آرام به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2289.gif', 'calves', 'hamstring', '1. Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.
2. Place your toes on the lever pad, with your heels hanging off the edge.
3. Grasp the handles or side supports for stability.
4. Push the lever pad down by extending your ankles, contracting your calf muscles.
5. Pause for a moment at the bottom of the movement.
6. Slowly return to the starting position by allowing your heels to rise back up.
7. Repeat for the desired number of repetitions.', '2289') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0576', 'پرس سینه دستگاه (نسخه ۲)', 'Lever chest press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر صاف به پد بنشینید.
۲. دستگیره‌ها را از رو بگیرید و آرنج‌ها را ۹۰ درجه خم کنید.
۳. دستگیره‌ها را به جلو هل دهید تا دست‌ها کاملاً صاف شوند و هنگام حرکت بازدم کنید.
۴. در انتهای حرکت لحظه‌ای مکث کنید، سپس با دم آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0576.gif', 'chest', 'triceps,deltoids', '1. Adjust the seat height and position yourself on the machine with your back flat against the pad.
2. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.
3. Push the handles forward until your arms are fully extended, exhaling during the movement.
4. Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.
5. Repeat for the desired number of repetitions.', '0576') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0578', 'ددلیفت دستگاه', 'Lever deadlift', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. ارتفاع صندلی و سکوی پا را در وضعیت دلخواه تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد و کف پاها روی سکو باشد.
۳. برای ثبات دستگیره‌ها یا کناره‌های صندلی را بگیرید.
۴. باسن و همسترینگ را درگیر کنید و با فشار پاشنه‌ها وزنه را بلند کنید.
۵. کمر را صاف نگه دارید و از گرد کردن شانه‌ها خودداری کنید.
۶. در اوج حرکت لگن را کاملاً باز کنید و باسن را منقبض کنید.
۷. وزنه را با کنترل پایین بیاورید و باسن و همسترینگ را درگیر نگه دارید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0578.gif', 'gluteal', 'hamstring,quadriceps', '1. Adjust the seat height and foot platform to your desired position.
2. Sit on the machine with your back against the pad and your feet flat on the foot platform.
3. Grasp the handles or the sides of the seat for stability.
4. Engage your glutes and hamstrings, and push through your heels to lift the weight up.
5. Keep your back straight and avoid rounding your shoulders.
6. Extend your hips fully at the top of the movement, squeezing your glutes.
7. Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.
8. Repeat for the desired number of repetitions.', '0578') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1300', 'پرس زیرسینه دستگاه', 'Lever decline chest press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. ارتفاع صندلی و پشتی دستگاه را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پشتی و کف پاها روی زمین باشد.
۳. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۴. دستگیره‌ها را به جلو و دور از بدن هل دهید تا دست‌ها کاملاً صاف شوند.
۵. دستگیره‌ها را آرام به سمت سینه برگردانید و آرنج‌ها را کمی خم نگه دارید.
۶. لحظه‌ای در پایین مکث کنید، سپس دستگیره‌ها را به وضعیت شروع هل دهید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1300.gif', 'chest', 'triceps,deltoids', '1. Adjust the seat height and backrest of the leverage machine to a comfortable position.
2. Sit on the machine with your back against the backrest and your feet flat on the floor.
3. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.
4. Push the handles forward and away from your body until your arms are fully extended.
5. Slowly lower the handles back towards your chest, keeping your elbows slightly bent.
6. Pause for a moment at the bottom, then push the handles back to the starting position.
7. Repeat for the desired number of repetitions.', '1300') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1253', 'ساق پا خرکی دستگاه', 'Lever donkey calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. دستگاه را در ارتفاع مناسب بدن خود تنظیم کنید.
۲. رو به دستگاه قرار بگیرید، پنجه‌ها روی سکو و پاشنه‌ها از لبه آزاد باشند.
۳. برای ثبات دست‌ها را روی دستگیره‌ها یا میله‌های تکیه‌گاه بگذارید.
۴. ساق‌ها را درگیر کنید و با کمک پنجه پاها پاشنه‌ها را تا جای ممکن بالا ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1253.gif', 'calves', 'hamstring,gluteal', '1. Adjust the leverage machine to the appropriate height for your body.
2. Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.
3. Place your hands on the handles or the support bars for stability.
4. Engage your calves and lift your heels as high as possible, using the balls of your feet.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '1253') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0579', 'زیربغل از جلو دستگاه', 'Lever front pulldown', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. ارتفاع صندلی را تنظیم کنید و طوری بنشینید که زانوها زیر پدها و کف پاها روی زمین باشد.
۲. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. صاف بنشینید، سینه را بالا و شانه‌ها را عقب نگه دارید و قوس ملایم کمر را حفظ کنید.
۴. زیربغل را درگیر کنید و دستگیره‌ها را به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در پایین حرکت مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0579.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.
4. Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.
6. Repeat for the desired number of repetitions.', '0579') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0580', 'شراگ بدون دستگیره دستگاه', 'Lever gripless shrug', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'کول (ذوزنقه)', 'شانه‌ها، ساعد', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه قرار بگیرید.
۲. دستگیره‌ها را با کف دست رو به داخل و دست‌های کاملاً صاف بگیرید.
۳. با کمر صاف و بازدم، شانه‌ها را تا جای ممکن بالا ببرید.
۴. انقباض را لحظه‌ای کوتاه نگه دارید، سپس با دم شانه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0580.gif', 'trapezius', 'deltoids,forearm', '1. Adjust the seat height and position yourself on the leverage machine.
2. Grasp the handles with your palms facing inwards and your arms fully extended.
3. Keeping your back straight, exhale and elevate your shoulders as high as possible.
4. Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', '0580') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1439', 'شراگ بدون دستگیره دستگاه (نسخه ۲)', 'Lever gripless shrug v. 2', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'کول (ذوزنقه)', 'شانه‌ها، ساعد', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پد بنشینید.
۲. دستگیره‌ها یا میله‌ها را از رو بگیرید و دست‌ها را صاف نگه دارید.
۳. با کمر صاف، شانه‌ها را تا جای ممکن به سمت گوش‌ها بالا ببرید.
۴. انقباض را لحظه‌ای نگه دارید، سپس شانه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1439.gif', 'trapezius', 'deltoids,forearm', '1. Adjust the seat height and position yourself on the machine with your back against the pad.
2. Grasp the handles or bars with an overhand grip, keeping your arms straight.
3. Keeping your back straight, lift your shoulders up towards your ears as high as possible.
4. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', '1439') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2288', 'تقویت پنجه دست دستگاه', 'Lever gripper hands', 'arms', 'بازو', 'machine', 'دستگاه', 'ساعد', 'جلو بازو، پشت بازو', '۱. ارتفاع صندلی را تنظیم کنید و دستگیره‌های دستگاه را بگیرید.
۲. کمر را صاف و کف پاها را روی زمین نگه دارید.
۳. با بازدم دستگیره‌ها را بفشارید و ساعدها را منقبض کنید.
۴. انقباض را یک ثانیه نگه دارید، سپس آرام رها کنید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2288.gif', 'forearm', 'biceps,triceps', '1. Adjust the seat height and grip the handles of the leverage machine.
2. Keep your back straight and your feet flat on the ground.
3. Exhale and squeeze the handles, contracting your forearms.
4. Hold the contraction for a second, then slowly release and return to the starting position.
5. Repeat for the desired number of repetitions.', '2288') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1615', 'جلو بازو لاری چکشی دستگاه', 'Lever hammer grip preacher curl', 'arms', 'بازو', 'machine', 'دستگاه', 'جلو بازو', 'ساعد', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه قرار بگیرید.
۲. بازوها را روی پد لاری بگذارید و مطمئن شوید سینه به آن فشرده شده است.
۳. دستگیره‌ها را به حالت چکشی (کف دست‌ها رو به هم) بگیرید.
۴. بازوها را ثابت نگه دارید و با بازدم دستگیره‌ها را به سمت شانه‌ها بالا بیاورید.
۵. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۶. با دم، دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1615.gif', 'biceps', 'forearm', '1. Adjust the seat height and position yourself on the leverage machine.
2. Place your upper arms on the preacher pad, ensuring your chest is pressed against it.
3. Grasp the handles with a hammer grip (palms facing each other).
4. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.
5. Pause for a moment at the top, squeezing your biceps.
6. Inhale and slowly lower the handles back to the starting position.
7. Repeat for the desired number of repetitions.', '1615') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0581', 'قایقی بالا دستگاه', 'Lever high row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، دلتوئید خلفی', '۱. ارتفاع صندلی و سکوی پا را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، سینه روی پد و کف پاها روی سکو باشد.
۳. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۴. کمر را صاف نگه دارید و میان‌تنه را درگیر کنید.
۵. دستگیره‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0581.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and foot platform to a comfortable position.
2. Sit on the machine with your chest against the pad and your feet flat on the foot platform.
3. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
4. Keep your back straight and engage your core.
5. Pull the handles towards your body, squeezing your shoulder blades together.
6. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.
7. Repeat for the desired number of repetitions.', '0581') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2286', 'باز کردن لگن دستگاه (نسخه ۲)', 'Lever hip extension v. 2', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'همسترینگ (پشت ران)', '۱. دستگاه را متناسب با بدن تنظیم کنید و با کمر به پشتی روی آن بنشینید.
۲. پاها را روی جاپایی بگذارید و برای ثبات دستگیره‌ها را بگیرید.
۳. باسن و همسترینگ را درگیر کنید، سپس با فشار به جاپایی لگن را باز کنید و پاها را به عقب ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2286.gif', 'gluteal', 'hamstring', '1. Adjust the machine to fit your body and sit on it with your back against the backrest.
2. Place your feet on the footrests and grip the handles for stability.
3. Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.
4. Pause for a moment at the top, then slowly lower your legs back to the starting position.
5. Repeat for the desired number of repetitions.', '2286') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2611', 'پرس پا تک‌پا افقی دستگاه', 'Lever horizontal one leg press', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. صندلی دستگاه را طوری تنظیم کنید که وقتی پاها روی سکو هستند زانوها ۹۰ درجه خم باشند.
۲. روی دستگاه بنشینید، کمر به پشتی و پاها به اندازه عرض شانه روی سکو باشد.
۳. برای ثبات دست‌ها را روی دستگیره‌ها یا کناره‌های دستگاه بگذارید.
۴. با باز کردن پا سکو را از بدن دور کنید و کمر را به پشتی تکیه داده نگه دارید.
۵. لحظه‌ای در حالت کاملاً باز مکث کنید، سپس پا را آرام خم کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2611.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.
2. Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.
3. Place your hands on the handles or sides of the machine for stability.
4. Push the footplate away from your body by extending your leg, keeping your back against the backrest.
5. Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '2611') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1299', 'پرس بالاسینه دستگاه', 'Lever incline chest press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'شانه‌ها، پشت بازو', '۱. صندلی و پشتی دستگاه را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پشتی و کف پاها روی زمین باشد.
۳. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۴. دستگیره‌ها را به جلو و دور از بدن هل دهید تا دست‌ها کاملاً صاف شوند.
۵. لحظه‌ای مکث کنید، سپس آرنج‌ها را آرام خم کنید و دستگیره‌ها را به سمت سینه برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1299.gif', 'chest', 'deltoids,triceps', '1. Adjust the seat and backrest of the leverage machine to a comfortable position.
2. Sit on the machine with your back against the backrest and your feet flat on the floor.
3. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.
4. Push the handles forward and away from your body until your arms are fully extended.
5. Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.
6. Repeat for the desired number of repetitions.', '1299') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1479', 'پرس بالاسینه دستگاه (نسخه ۲)', 'Lever incline chest press v. 2', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. ارتفاع صندلی و زاویه پشتی دستگاه را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پشتی و کف پاها روی زمین باشد.
۳. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۴. دستگیره‌ها را به جلو و دور از بدن هل دهید تا دست‌ها کاملاً صاف شوند، اما آرنج‌ها را قفل نکنید.
۵. لحظه‌ای در حالت کاملاً باز مکث کنید، سپس آرنج‌ها را آرام خم کنید و دستگیره‌ها را به سمت سینه برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1479.gif', 'chest', 'triceps,deltoids', '1. Adjust the seat height and backrest angle on the leverage machine to a comfortable position.
2. Sit on the machine with your back against the backrest and your feet flat on the floor.
3. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.
4. Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.
5. Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.
6. Repeat for the desired number of repetitions.', '1479') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0582', 'پشت پا زانو زده دستگاه', 'Lever kneeling leg curl', 'legs', 'پا', 'machine', 'دستگاه', 'همسترینگ (پشت ران)', 'سرینی (باسن)', '۱. دستگاه را متناسب با بدن تنظیم کنید و وزن دلخواه را انتخاب کنید.
۲. روی دستگاه رو به پایین زانو بزنید، زانوها روی پد و پاها زیر پدهای پا محکم باشد.
۳. برای ثبات دستگیره‌ها یا کناره‌های دستگاه را بگیرید.
۴. بالاتنه را ثابت نگه دارید و با بازدم، با خم کردن زانوها پاها را به سمت باسن بالا بیاورید.
۵. لحظه‌ای در اوج حرکت مکث کنید و همسترینگ را منقبض کنید.
۶. با دم، پاها را آرام به وضعیت شروع پایین بیاورید و زانوها را کاملاً باز کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0582.gif', 'hamstring', 'gluteal', '1. Adjust the machine to fit your body and select the desired weight.
2. Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.
3. Grasp the handles or the sides of the machine for stability.
4. Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.
5. Pause for a moment at the top of the movement, squeezing your hamstrings.
6. Inhale and slowly lower your legs back to the starting position, fully extending your knees.
7. Repeat for the desired number of repetitions.', '0582') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0583', 'چرخش تنه زانو زده دستگاه', 'Lever kneeling twist', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'شکم', 'پهلوها، پایین کمر', '۱. ارتفاع صندلی را تنظیم کنید و طوری قرار بگیرید که زانوها روی پدها و بالاتنه رو به جلو باشد.
۲. برای ثبات دستگیره‌ها یا کناره‌های دستگاه را بگیرید.
۳. با میان‌تنه درگیر، تنه را تا جایی که راحت هستید به یک طرف بچرخانید.
۴. لحظه‌ای مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. چرخش را به طرف مقابل تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0583.gif', 'abs', 'obliques,lower-back', '1. Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.
2. Grasp the handles or the sides of the machine for stability.
3. Keeping your core engaged, twist your torso to one side as far as comfortably possible.
4. Pause for a moment, then slowly return to the starting position.
5. Repeat the twist to the opposite side.
6. Continue alternating sides for the desired number of repetitions.', '0583') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0584', 'نشر جانب دستگاه', 'Lever lateral raise', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'کول (ذوزنقه)، بالای پشت', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پد بنشینید.
۲. دستگیره‌ها را از رو بگیرید و دست‌ها را صاف نگه دارید.
۳. با بازدم دست‌ها را به طرفین بالا ببرید تا موازی زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس با دم دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0584.gif', 'deltoids', 'trapezius,upper-back', '1. Adjust the seat height and position yourself on the machine with your back against the pad.
2. Grasp the handles with an overhand grip and keep your arms straight.
3. Exhale and raise your arms out to the sides until they are parallel to the floor.
4. Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.
5. Repeat for the desired number of repetitions.', '0584') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3195', 'پشت پا خوابیده دو پا و تک‌پا دستگاه', 'Lever lying two-one leg curl', 'legs', 'پا', 'machine', 'دستگاه', 'همسترینگ (پشت ران)', 'سرینی (باسن)', '۱. دستگاه را متناسب با بدن تنظیم کنید و با کمر به پشتی روی آن بنشینید.
۲. پاها را روی پد اهرم، کمی بالاتر از مچ پاها قرار دهید.
۳. برای حمایت دستگیره‌های کنار دستگاه را بگیرید.
۴. بالاتنه را ثابت نگه دارید و با بازدم پاها را به سمت باسن بالا بیاورید.
۵. لحظه‌ای در بالا مکث کنید، سپس با دم پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3195.gif', 'hamstring', 'gluteal', '1. Adjust the machine to fit your body and sit on it with your back against the backrest.
2. Place your legs on the lever pad, just above your ankles.
3. Grasp the handles on the sides of the machine for support.
4. Keeping your upper body still, exhale and curl your legs up towards your glutes.
5. Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.
6. Repeat for the desired number of repetitions.', '3195') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0587', 'پرس نظامی دستگاه', 'Lever military press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، بالاسینه', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پشتی بنشینید.
۲. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. دستگیره‌ها را بالا هل دهید تا دست‌ها کاملاً صاف شوند، اما آرنج‌ها را قفل نکنید.
۴. لحظه‌ای در بالا مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0587.gif', 'deltoids', 'triceps,chest', '1. Adjust the seat height and position yourself on the machine with your back against the backrest.
2. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.
3. Push the handles upward until your arms are fully extended, but do not lock your elbows.
4. Pause for a moment at the top, then slowly lower the handles back down to the starting position.
5. Repeat for the desired number of repetitions.', '0587') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0588', 'قایقی نشسته دست جمع دستگاه', 'Lever narrow grip seated row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. ارتفاع صندلی و جاپایی را برای فرم صحیح تنظیم کنید.
۲. روی دستگاه بنشینید، پاها روی جاپایی و زانوها کمی خم باشد.
۳. دستگیره‌ها را با دست‌های جمع و کف دست‌های رو به هم بگیرید.
۴. کمر را صاف نگه دارید و کمی به جلو متمایل شوید.
۵. دستگیره‌ها را به سمت تنه بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید.
۷. دستگیره‌ها را آرام رها کنید و به وضعیت شروع برگردید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0588.gif', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and footrests to ensure proper form.
2. Sit on the machine with your feet flat on the footrests and your knees slightly bent.
3. Grasp the handles with a narrow grip, palms facing each other.
4. Keep your back straight and lean slightly forward.
5. Pull the handles towards your torso, squeezing your shoulder blades together.
6. Pause for a moment at the peak of the movement.
7. Slowly release the handles and return to the starting position.
8. Repeat for the desired number of repetitions.', '0588') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0589', 'زیربغل خم تک‌دست دستگاه', 'Lever one arm bent over row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز و زانوها کمی خم باشد و هالتر را از رو بگیرید.
۲. از لگن به جلو خم شوید و کمر را صاف و سر را بالا نگه دارید.
۳. اجازه دهید هالتر با دست‌های کاملاً صاف جلوی شما آویزان باشد.
۴. هالتر را به سمت سینه بالا بکشید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. در اوج حرکت کتف‌ها را به هم فشار دهید.
۶. هالتر را به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0589.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.
2. Bend forward at the hips, keeping your back straight and your head up.
3. Let the barbell hang in front of you with your arms fully extended.
4. Pull the barbell up towards your chest, keeping your elbows close to your body.
5. Squeeze your shoulder blades together at the top of the movement.
6. Lower the barbell back down to the starting position.
7. Repeat for the desired number of repetitions.', '0589') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1356', 'قایقی بالا جانبی تک‌دست دستگاه', 'Lever one arm lateral high row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. ارتفاع صندلی را تنظیم کنید و رو به دستگاه قرار بگیرید.
۲. دستگیره را با یک دست بگیرید و کمر را صاف نگه دارید.
۳. دستگیره را به سمت بدن بکشید و آرنج را نزدیک پهلو نگه دارید.
۴. در اوج حرکت عضلات پشت را منقبض کنید.
۵. دستگیره را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1356.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself facing the machine.
2. Grasp the handle with one hand and keep your back straight.
3. Pull the handle towards your body, keeping your elbow close to your side.
4. Squeeze your back muscles at the top of the movement.
5. Slowly release the handle back to the starting position.
6. Repeat for the desired number of repetitions.', '1356') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1347', 'زیربغل دست باز جانبی تک‌دست دستگاه', 'Lever one arm lateral wide pulldown', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. ارتفاع صندلی را تنظیم کنید و طوری بنشینید که سینه روی پد و کف پاها روی زمین باشد.
۲. دستگیره را از رو بگیرید و دست را کاملاً صاف کنید و آرنج را کمی خم نگه دارید.
۳. دستگیره را به سمت پایین و از جلوی بدن به سمت لگن مخالف بکشید و در پایین حرکت زیربغل را منقبض کنید.
۴. دستگیره را آرام به وضعیت شروع برگردانید و دست را کاملاً صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1347.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.
2. Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.
3. Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.
4. Slowly return the handle to the starting position, fully extending your arm.
5. Repeat for the desired number of repetitions, then switch sides.', '1347') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0590', 'پرس سرشانه تک‌دست دستگاه', 'Lever one arm shoulder press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، بالای پشت', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پد بنشینید.
۲. دستگیره اهرم را با یک دست بگیرید و آرنج را ۹۰ درجه خم کنید.
۳. اهرم را بالا پرس کنید تا دست کاملاً بالای سر صاف شود.
۴. لحظه‌ای در بالا مکث کنید، سپس اهرم را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0590.gif', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height and position yourself on the machine with your back against the pad.
2. Grasp the lever handle with one hand and position your elbow at a 90-degree angle.
3. Press the lever upward until your arm is fully extended overhead.
4. Pause for a moment at the top, then slowly lower the lever back down to the starting position.
5. Repeat for the desired number of repetitions, then switch to the other arm.', '0590') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0591', 'دیپ پشت بازو دست از رو دستگاه', 'Lever overhand triceps dip', 'arms', 'بازو', 'machine', 'دستگاه', 'پشت بازو', 'سینه، شانه‌ها', '۱. دستگاه را در ارتفاع مناسب تنظیم کنید و بدن را در جای خود محکم کنید.
۲. دستگیره‌ها را از رو بگیرید و طوری قرار بگیرید که دست‌ها کاملاً صاف باشند.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید و بازوها را نزدیک پهلوها نگه دارید.
۴. تا جایی پایین بروید که بازوها موازی زمین شوند.
۵. لحظه‌ای مکث کنید، سپس با صاف کردن آرنج‌ها خود را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0591.gif', 'triceps', 'chest,deltoids', '1. Adjust the machine to the appropriate height and secure your body in position.
2. Grasp the handles with an overhand grip and position your body so that your arms are fully extended.
3. Lower your body by bending your elbows, keeping your upper arms close to your sides.
4. Continue lowering until your upper arms are parallel to the floor.
5. Pause for a moment, then push yourself back up to the starting position by extending your elbows.
6. Repeat for the desired number of repetitions.', '0591') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0592', 'جلو بازو لاری دستگاه', 'Lever preacher curl', 'arms', 'بازو', 'machine', 'دستگاه', 'جلو بازو', 'ساعد', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه قرار بگیرید.
۲. بازوها را روی پد بگذارید و دستگیره‌ها را از زیر بگیرید.
۳. کمر را صاف و آرنج‌ها را روی پد نگه دارید.
۴. با بازدم ساعدها را به سمت بازوها خم کنید و جلو بازو را منقبض کنید.
۵. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۶. با دم، دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0592.gif', 'biceps', 'forearm', '1. Adjust the seat height and position yourself on the leverage machine.
2. Place your upper arms on the pad and grip the handles with an underhand grip.
3. Keep your back straight and your elbows positioned on the pad.
4. Exhale and curl your forearms towards your upper arms, contracting your biceps.
5. Pause for a moment at the top of the movement, squeezing your biceps.
6. Inhale and slowly lower the handles back to the starting position.
7. Repeat for the desired number of repetitions.', '0592') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1614', 'جلو بازو لاری دستگاه (نسخه ۲)', 'Lever preacher curl v. 2', 'arms', 'بازو', 'machine', 'دستگاه', 'جلو بازو', 'ساعد', '۱. ارتفاع صندلی را تنظیم کنید و طوری بنشینید که بازوها روی پد و سینه به تکیه‌گاه باشد.
۲. دستگیره‌ها را از زیر و کمی بازتر از عرض شانه بگیرید.
۳. بازوها را ثابت نگه دارید و با بازدم دستگیره‌ها را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1614.gif', 'biceps', 'forearm', '1. Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.
2. Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.
3. Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.
4. Pause for a moment at the top of the movement, squeezing your biceps.
5. Inhale as you slowly lower the handles back to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '1614') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2285', 'پول‌اور دستگاه', 'Lever pullover', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'پشت بازو، شانه‌ها', '۱. صندلی و دستگیره‌های دستگاه را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد باشد و دستگیره‌ها را از رو بگیرید.
۳. دست‌ها را کمی خم و میان‌تنه را درگیر نگه دارید.
۴. دستگیره‌ها را آرام به سمت سینه بکشید و زیربغل را منقبض کنید.
۵. لحظه‌ای در اوج انقباض مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2285.gif', 'upper-back', 'triceps,deltoids', '1. Adjust the seat and handles of the leverage machine to a comfortable position.
2. Sit on the machine with your back against the pad and grasp the handles with an overhand grip.
3. Keep your arms slightly bent and your core engaged.
4. Slowly pull the handles towards your chest, squeezing your lats.
5. Pause for a moment at the peak contraction, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '2285') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2736', 'زیربغل دست‌برعکس دستگاه', 'Lever reverse grip lateral pulldown', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. ارتفاع صندلی را تنظیم کنید و طوری بنشینید که زانوها زیر پدها و کف پاها روی زمین باشد.
۲. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. صاف بنشینید، سینه جلو و شانه‌ها عقب باشد و قوس ملایم کمر را حفظ کنید.
۴. دستگیره‌ها را با هدایت آرنج‌ها به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در پایین حرکت مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2736.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.
4. Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.
5. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.
6. Repeat for the desired number of repetitions.', '2736') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1616', 'جلو بازو لاری دست‌برعکس دستگاه', 'Lever reverse grip preacher curl', 'arms', 'بازو', 'machine', 'دستگاه', 'جلو بازو', 'ساعد', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه قرار بگیرید.
۲. دستگیره‌ها را از زیر با کف دست رو به بالا بگیرید.
۳. بازوها را روی پد لاری بگذارید و مطمئن شوید آرنج‌ها کاملاً صاف هستند.
۴. بازوها را ثابت نگه دارید و با بازدم دستگیره‌ها را به سمت شانه‌ها بالا بیاورید.
۵. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۶. با دم، دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید و آرنج‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1616.gif', 'biceps', 'forearm', '1. Adjust the seat height and position yourself on the leverage machine.
2. Grasp the handles with an underhand grip, palms facing up.
3. Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.
4. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.
5. Pause for a moment at the top of the movement, squeezing your biceps.
6. Inhale and slowly lower the handles back to the starting position, fully extending your elbows.
7. Repeat for the desired number of repetitions.', '1616') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1348', 'قایقی عمودی دست‌برعکس دستگاه', 'Lever reverse grip vertical row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. ارتفاع صندلی و جای پا را برای قرارگیری صحیح تنظیم کنید.
۲. روی دستگاه بنشینید، سینه روی پد و کف پاها روی جای پا باشد.
۳. دستگیره‌ها را از زیر با کف دست رو به بالا بگیرید.
۴. کمر را صاف نگه دارید و میان‌تنه را درگیر کنید.
۵. دستگیره‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید، سپس آرام رها کنید و دست‌ها را به وضعیت شروع صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1348.gif', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and footplate position to ensure proper alignment.
2. Sit on the machine with your chest against the pad and your feet flat on the footplate.
3. Grasp the handles with an underhand grip, palms facing up.
4. Keep your back straight and engage your core.
5. Pull the handles towards your chest, squeezing your shoulder blades together.
6. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.
7. Repeat for the desired number of repetitions.', '1348') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0593', 'فیله کمر معکوس دستگاه', 'Lever reverse hyperextension', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. دستگاه را متناسب با بدن تنظیم کنید و پاها را در پدهای پا محکم کنید.
۲. روی دستگاه دمر دراز بکشید، بالاتنه از لبه آویزان و لگن روی پد باشد.
۳. دست‌ها را روی سینه ضربدری کنید یا پشت سر بگذارید.
۴. باسن و همسترینگ را درگیر کنید و پاها را بالا ببرید تا موازی زمین شوند.
۵. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0593.gif', 'gluteal', 'hamstring,lower-back', '1. Adjust the leverage machine to fit your body and secure your feet in the foot pads.
2. Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.
3. Cross your arms over your chest or place them behind your head.
4. Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.
5. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '0593') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2315', 'ساق پا چرخشی دستگاه', 'Lever rotary calf', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'نعلی، تثبیت‌کننده‌های مچ پا', '۱. ارتفاع صندلی را طوری تنظیم کنید که زانوها کمی خم و کف پاها روی سکو باشد.
۲. پنجه‌ها را روی سکو بگذارید و پاشنه‌ها از لبه آزاد باشند.
۳. برای ثبات دستگیره‌ها یا کناره‌های دستگاه را بگیرید.
۴. با فشار پنجه پاها، پاشنه‌ها را تا جای ممکن بالا ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2315.gif', 'calves', '', '1. Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.
2. Place your toes on the footplate, with your heels hanging off the edge.
3. Grasp the handles or the sides of the machine for stability.
4. Push through the balls of your feet, raising your heels as high as possible.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '2315') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2335', 'ساق پا پرسی نشسته دستگاه', 'Lever seated calf press', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'نعلی، همسترینگ (پشت ران)', '۱. صندلی دستگاه را طوری تنظیم کنید که شانه‌ها هم‌تراز با پد اهرم باشند.
۲. پنجه‌ها را روی قسمت پایین سکو بگذارید و زانوها را زیر پد اهرم قرار دهید.
۳. برای ثبات دستگیره‌های کنار صندلی را بگیرید.
۴. با باز کردن مچ پاها پد اهرم را فشار دهید و پاشنه‌ها را تا جای ممکن بالا ببرید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2335.gif', 'calves', 'hamstring', '1. Adjust the seat of the machine so that your shoulders are aligned with the lever pad.
2. Place your toes on the lower portion of the platform and position your knees under the lever pad.
3. Grasp the handles on the sides of the seat for stability.
4. Press the lever pad down by extending your ankles, lifting your heels as high as possible.
5. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '2335') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0594', 'ساق پا نشسته دستگاه', 'Lever seated calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'نعلی، تثبیت‌کننده‌های مچ پا', '۱. ارتفاع صندلی را طوری تنظیم کنید که زانوها کمی خم و کف پاها روی سکو باشد.
۲. پنجه‌ها را روی سکو بگذارید و پاشنه‌ها از لبه آزاد باشند.
۳. برای ثبات دستگیره‌ها یا کناره‌های صندلی را بگیرید.
۴. با فشار پنجه پاها، پاشنه‌ها را تا جای ممکن بالا ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0594.gif', 'calves', '', '1. Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.
2. Place your toes on the footplate with your heels hanging off the edge.
3. Grasp the handles or the sides of the seat for stability.
4. Push through the balls of your feet to raise your heels as high as possible.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '0594') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1452', 'کرانچ نشسته دستگاه', 'Lever seated crunch', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'شکم', 'پهلوها', '۱. روی دستگاه بنشینید، کمر به پد و کف پاها روی زمین باشد.
۲. برای حمایت دستگیره‌ها را بگیرید یا دست‌ها را روی پدهای کناری بگذارید.
۳. شکم را درگیر کنید و آرام به عقب متمایل شوید و اجازه دهید پد همراه شما حرکت کند.
۴. وقتی بالاتنه به زاویه ۴۵ درجه رسید، شکم را منقبض کنید و به جلو کرانچ کنید و سینه را به سمت زانوها ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1452.gif', 'abs', 'obliques', '1. Sit on the leverage machine with your back against the pad and your feet flat on the floor.
2. Grasp the handles or place your hands on the side pads for support.
3. Engage your abs and slowly lean back, allowing the pad to move with you.
4. Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.
5. Pause for a moment at the top, then slowly release and return to the starting position.
6. Repeat for the desired number of repetitions.', '1452') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0595', 'کرانچ نشسته دستگاه (پد سینه)', 'Lever seated crunch (chest pad)', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'شکم', 'پهلوها', '۱. ارتفاع صندلی و جای پد سینه را مطابق راحتی خود تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد سینه و کف پاها روی زمین باشد.
۳. برای ثبات دستگیره‌ها یا میله‌های کناری را بگیرید.
۴. شکم را درگیر کنید و آرام به عقب متمایل شوید و اجازه دهید پد سینه همراه شما حرکت کند.
۵. لحظه‌ای در حداکثر انقباض مکث کنید و فشار را در شکم حس کنید.
۶. با انقباض شکم خود را بالا بکشید و آرام به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0595.gif', 'abs', 'obliques', '1. Adjust the seat height and chest pad position according to your comfort.
2. Sit on the machine with your back against the chest pad and your feet flat on the floor.
3. Grasp the handles or side bars for stability.
4. Engage your abs and slowly lean back, allowing the chest pad to move with you.
5. Pause for a moment at the maximum contraction, feeling the tension in your abs.
6. Slowly return to the starting position by contracting your abs and pulling yourself back up.
7. Repeat for the desired number of repetitions.', '0595') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3760', 'کرانچ نشسته دستگاه (نسخه ۲)', 'Lever seated crunch v. 2', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'شکم', 'پهلوها، خم‌کننده ران', '۱. روی دستگاه بنشینید، کمر به پد و پاها زیر پدهای پا محکم باشد.
۲. برای حمایت دست‌ها را روی دستگیره‌ها یا کناره‌های صندلی بگذارید.
۳. شکم را درگیر کنید و آرام به جلو کرانچ کنید و سینه را به سمت زانوها ببرید.
۴. لحظه‌ای در اوج حرکت مکث کنید و شکم را منقبض کنید.
۵. آرام به وضعیت شروع برگردید و اجازه دهید کمر کمی گرد شود.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3760.gif', 'abs', 'obliques,hip-flexors', '1. Sit on the leverage machine with your back against the pad and your feet secured under the footpads.
2. Place your hands on the handles or the sides of the seat for support.
3. Engage your abs and slowly crunch forward, bringing your chest towards your knees.
4. Pause for a moment at the top of the movement, squeezing your abs.
5. Slowly return to the starting position, allowing your back to round slightly.
6. Repeat for the desired number of repetitions.', '3760') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1451', 'دیپ نشسته دستگاه', 'Lever seated dip', 'arms', 'بازو', 'machine', 'دستگاه', 'پشت بازو', 'سینه، شانه‌ها', '۱. ارتفاع صندلی را طوری تنظیم کنید که کف پاها روی زمین و زانوها ۹۰ درجه باشد.
۲. دستگیره‌های دستگاه را با کف دست رو به پایین و دست‌های کاملاً صاف بگیرید.
۳. با خم کردن آرنج‌ها بدن را آرام پایین ببرید تا بازوها موازی زمین شوند.
۴. لحظه‌ای مکث کنید، سپس با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1451.gif', 'triceps', 'chest,deltoids', '1. Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.
2. Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.
3. Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.
4. Pause for a moment, then push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '1451') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0596', 'قفسه نشسته دستگاه (پک دک)', 'Lever seated fly', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'سرشانه، کول (ذوزنقه)', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پد بنشینید.
۲. دستگیره‌ها را از رو بگیرید و آرنج‌ها را کمی خم نگه دارید.
۳. با بازدم دستگیره‌ها را به جلو هل دهید و جلوی سینه به هم برسانید.
۴. لحظه‌ای مکث کنید و عضلات سینه را منقبض کنید.
۵. با دم، آرام به وضعیت شروع برگردید و اجازه دهید عضلات سینه کشیده شوند.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0596.gif', 'chest', 'deltoids,trapezius', '1. Adjust the seat height and position yourself on the machine with your back against the pad.
2. Grasp the handles with a pronated grip and keep your elbows slightly bent.
3. Exhale and push the handles forward, bringing them together in front of your chest.
4. Pause for a moment, squeezing your chest muscles.
5. Inhale and slowly return to the starting position, allowing your chest muscles to stretch.
6. Repeat for the desired number of repetitions.', '0596') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3759', 'گودمورنینگ نشسته دستگاه', 'Lever seated good morning', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. ارتفاع صندلی را طوری تنظیم کنید که لگن کمی بالاتر از زانوها باشد.
۲. روی دستگاه بنشینید، کمر به پد و کف پاها روی جاپایی باشد.
۳. برای ثبات دستگیره‌ها یا کناره‌های صندلی را بگیرید.
۴. با کمر صاف، آرام از لگن به جلو خم شوید تا بالاتنه موازی زمین شود.
۵. لحظه‌ای مکث کنید، سپس با کمک باسن و همسترینگ آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3759.gif', 'gluteal', 'hamstring,lower-back', '1. Adjust the seat height so that your hips are slightly higher than your knees.
2. Sit on the machine with your back against the pad and your feet flat on the footrests.
3. Grasp the handles or the sides of the seat for stability.
4. Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.
5. Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.
6. Repeat for the desired number of repetitions.', '3759') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0597', 'دور کردن ران نشسته دستگاه', 'Lever seated hip abduction', 'legs', 'پا', 'machine', 'دستگاه', 'دورکننده ران', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. ارتفاع صندلی را طوری تنظیم کنید که زانوها ۹۰ درجه باشند.
۲. روی دستگاه بنشینید، کمر به پشتی و پاها روی جاپایی باشد.
۳. برای ثبات دست‌ها را روی دستگیره‌های کناری بگذارید.
۴. عضلات دورکننده ران را درگیر کنید و پاها را آرام از خط وسط بدن دور کنید.
۵. لحظه‌ای در انتهای حرکت مکث کنید، سپس پاها را آرام به هم نزدیک کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0597.gif', 'gluteal', 'hamstring', '1. Adjust the seat height so that your knees are at a 90-degree angle.
2. Sit on the machine with your back against the backrest and your feet on the footrests.
3. Place your hands on the side handles for stability.
4. Engage your abductors and slowly push your legs apart, away from the midline of your body.
5. Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.
6. Repeat for the desired number of repetitions.', '0597') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0598', 'نزدیک کردن ران نشسته دستگاه', 'Lever seated hip adduction', 'legs', 'پا', 'machine', 'دستگاه', 'نزدیک‌کننده ران', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پشتی بنشینید.
۲. پاها را روی جاپایی بگذارید و برای ثبات دستگیره‌ها را بگیرید.
۳. عضلات نزدیک‌کننده ران را درگیر کنید و پاها را آرام به هم نزدیک کنید و داخل ران‌ها را منقبض کنید.
۴. لحظه‌ای در اوج انقباض مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0598.gif', 'adductors', 'hamstring,gluteal', '1. Adjust the seat height and position yourself on the machine with your back against the backrest.
2. Place your feet on the footrests and grasp the handles for stability.
3. Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.
4. Pause for a moment at the peak contraction, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0598') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0599', 'پشت پا نشسته دستگاه', 'Lever seated leg curl', 'legs', 'پا', 'machine', 'دستگاه', 'همسترینگ (پشت ران)', 'ساق پا', '۱. دستگاه را متناسب با بدن تنظیم کنید و با کمر به پشتی روی آن بنشینید.
۲. ساق پاها را زیر اهرم پددار، کمی بالاتر از مچ پاها قرار دهید.
۳. برای حمایت دستگیره‌های کنار دستگاه را بگیرید.
۴. ران‌ها را ثابت نگه دارید و با بازدم پاها را تا جای ممکن خم کنید.
۵. وضعیت انقباض را لحظه‌ای نگه دارید و همسترینگ را بفشارید.
۶. با دم، اهرم را آرام به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0599.gif', 'hamstring', 'calves', '1. Adjust the machine to fit your body and sit on it with your back against the backrest.
2. Place your lower legs under the padded lever, just above your ankles.
3. Grasp the handles on the sides of the machine for support.
4. Keeping your upper legs stationary, exhale and curl your legs up as far as possible.
5. Hold the contracted position for a brief pause as you squeeze your hamstrings.
6. Inhale and slowly lower the lever back to the starting position.
7. Repeat for the desired number of repetitions.', '0599') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0600', 'کرانچ با بالا آوردن پا نشسته دستگاه', 'Lever seated leg raise crunch', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'شکم', 'خم‌کننده ران', '۱. روی دستگاه بنشینید، کمر به پشتی و پاها روی جاپایی باشد.
۲. برای ثبات دستگیره‌ها یا میله‌های کناری را بگیرید.
۳. شکم را درگیر کنید و پاها را آرام به سمت سینه بالا بیاورید و همزمان تنه را به جلو خم کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها و تنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0600.gif', 'abs', 'hip-flexors', '1. Sit on the leverage machine with your back against the backrest and your feet on the footrests.
2. Grasp the handles or sidebars for stability.
3. Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.
4. Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.
5. Repeat for the desired number of repetitions.', '0600') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0602', 'قفسه معکوس نشسته دستگاه', 'Lever seated reverse fly', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. ارتفاع صندلی را تنظیم کنید و طوری بنشینید که سینه روی پد و کف پاها روی زمین باشد.
۲. دستگیره‌ها را از رو بگیرید و دست‌ها را کمی خم نگه دارید.
۳. با بازدم کتف‌ها را به هم فشار دهید و دستگیره‌ها را به عقب و بیرون، دور از بدن بکشید.
۴. لحظه‌ای در اوج انقباض مکث کنید، سپس با دم آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0602.gif', 'deltoids', 'trapezius,upper-back', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.
2. Grasp the handles with an overhand grip and keep your arms slightly bent.
3. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.
4. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0602') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0601', 'قفسه معکوس نشسته دستگاه (دست موازی)', 'Lever seated reverse fly (parallel grip)', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. ارتفاع صندلی را تنظیم کنید و طوری بنشینید که سینه روی پد و کف پاها روی زمین باشد.
۲. دستگیره‌ها را به صورت موازی با کف دست‌های رو به هم بگیرید و دست‌ها را کمی خم نگه دارید.
۳. با بازدم کتف‌ها را به هم فشار دهید و دستگیره‌ها را به عقب و بیرون، دور از بدن بکشید.
۴. لحظه‌ای در اوج انقباض مکث کنید، سپس با دم آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0601.gif', 'deltoids', 'trapezius,upper-back', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.
2. Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.
3. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.
4. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0601') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1350', 'قایقی نشسته دستگاه', 'Lever seated row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. ارتفاع صندلی و جاپایی را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، سینه روی پد و پاها روی جاپایی باشد.
۳. دستگیره‌ها را از رو و به اندازه عرض شانه بگیرید.
۴. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. دستگیره‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید.
۷. دستگیره‌ها را آرام رها کنید و به وضعیت شروع برگردید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1350.gif', 'upper-back', 'biceps,forearm', '1. Adjust the seat height and footrests to a comfortable position.
2. Sit on the machine with your chest against the pad and your feet on the footrests.
3. Grasp the handles with an overhand grip, shoulder-width apart.
4. Keep your back straight and your core engaged.
5. Pull the handles towards your body, squeezing your shoulder blades together.
6. Pause for a moment at the peak of the movement.
7. Slowly release the handles and return to the starting position.
8. Repeat for the desired number of repetitions.', '1350') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1385', 'ساق پا اسکوات نشسته روی دستگاه پرس پا', 'Lever seated squat calf raise on leg press machine', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'چهارسر ران، همسترینگ (پشت ران)، سرینی (باسن)', '۱. صندلی دستگاه پرس پا را طوری تنظیم کنید که وقتی پاها روی سکو هستند زانوها کمی خم باشند.
۲. روی دستگاه بنشینید، کمر به پشتی و پاها به اندازه عرض شانه روی سکو باشد.
۳. پنجه‌ها و جلوی کف پا را روی سکو بگذارید و پاشنه‌ها را آزاد نگه دارید.
۴. دستگیره‌های ایمنی را آزاد کنید و با باز کردن زانوها سکو را از خود دور کنید.
۵. وقتی زانوها کاملاً باز شدند، با خم کردن مچ پا پاشنه‌ها را آرام پایین ببرید.
۶. لحظه‌ای در پایین مکث کنید، سپس با باز کردن مچ پا سکو را دوباره بالا ببرید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1385.gif', 'calves', 'quadriceps,hamstring,gluteal', '1. Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.
2. Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.
3. Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.
4. Release the safety handles and push the footplate away from you by extending your knees.
5. Once your knees are fully extended, slowly lower your heels by flexing your calves.
6. Pause for a moment at the bottom, then push the footplate back up by extending your calves.
7. Repeat for the desired number of repetitions.', '1385') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0603', 'پرس سرشانه دستگاه', 'Lever shoulder press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، سینه', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پشتی بنشینید.
۲. دستگیره‌ها را از رو بگیرید و دست‌ها را در سطح شانه قرار دهید.
۳. دستگیره‌ها را بالا هل دهید تا دست‌ها کاملاً صاف شوند، اما آرنج‌ها را قفل نکنید.
۴. لحظه‌ای در بالا مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0603.gif', 'deltoids', 'triceps,chest', '1. Adjust the seat height and position yourself on the machine with your back against the backrest.
2. Grasp the handles with an overhand grip and position your hands at shoulder level.
3. Push the handles upward until your arms are fully extended, but do not lock your elbows.
4. Pause for a moment at the top, then slowly lower the handles back down to the starting position.
5. Repeat for the desired number of repetitions.', '0603') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0869', 'پرس سرشانه دستگاه (نسخه ۲)', 'Lever shoulder press v. 2', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، سینه', '۱. ارتفاع صندلی و پشتی دستگاه را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پشتی و کف پاها روی زمین باشد.
۳. دستگیره‌های دستگاه را از رو و کمی بازتر از عرض شانه بگیرید.
۴. دستگیره‌ها را به بالا و جلو هل دهید تا دست‌ها کاملاً صاف شوند، اما قفل نشوند.
۵. لحظه‌ای در بالا مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0869.gif', 'deltoids', 'triceps,chest', '1. Adjust the seat height and backrest of the leverage machine to a comfortable position.
2. Sit on the machine with your back against the backrest and your feet flat on the floor.
3. Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.
4. Push the handles upward and forward until your arms are fully extended, but not locked.
5. Pause for a moment at the top, then slowly lower the handles back down to the starting position.
6. Repeat for the desired number of repetitions.', '0869') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
