INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0604', 'شراگ دستگاه', 'Lever shrug', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'کول (ذوزنقه)', 'شانه‌ها', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کمر به پد بنشینید.
۲. دستگیره‌ها را از رو بگیرید و دست‌ها را صاف نگه دارید.
۳. با کمر صاف، شانه‌ها را تا جای ممکن به سمت گوش‌ها بالا ببرید.
۴. انقباض را لحظه‌ای نگه دارید، سپس شانه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0604.gif', 'trapezius', 'deltoids', '1. Adjust the seat height and position yourself on the leverage machine with your back against the pad.
2. Grasp the handles with an overhand grip and keep your arms straight.
3. Keeping your back straight, lift your shoulders up towards your ears as high as possible.
4. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', '0604') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3758', 'پرس سینه ایستاده دستگاه', 'Lever standing chest press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'شانه‌ها، پشت بازو', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه بنشینید و کف پاها روی زمین باشد.
۲. دستگیره‌ها را از رو بگیرید و دست‌ها را در سطح سینه قرار دهید.
۳. دستگیره‌ها را به جلو هل دهید تا دست‌ها کاملاً صاف شوند و آرنج‌ها را کمی خم نگه دارید.
۴. لحظه‌ای مکث کنید، سپس دستگیره‌ها را آرام و با کنترل به سمت سینه برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3758.gif', 'chest', 'deltoids,triceps', '1. Adjust the seat height and position yourself on the machine with your feet flat on the ground.
2. Grasp the handles with an overhand grip and position your hands at chest level.
3. Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.
4. Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.
5. Repeat for the desired number of repetitions.', '3758') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
